-- Adds verified quotes and restores quotes MS-800 un-verified for a missing work, each checked word for word against
-- its cited work. seed_quotes.sql already carries these values.
-- Run in the Supabase SQL Editor after the server has started on this release (it adds works.for_quotes_only)
-- and after seed_works.sql has been re-run (it is an upsert). Each statement matches on figure and text, so re-running
-- changes nothing: when a later release appends a block, run the whole script again and only the new block applies.
BEGIN;

-- Restore or correct (24)
UPDATE quotes SET source = 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor and the China Inland Mission, ch. 19 (1918)', text = 'How many estimate difficulties in the light of their own resources, and thus attempt little and often fail in the little they attempt! All God''s giants have been weak men, who did great things for God because they reckoned on His being with them.', verified = true WHERE figure_id = 82 AND text = 'All God''s giants have been weak men who did great things for God because they reckoned on His being with them.';
UPDATE quotes SET source = 'Cited in Howard Taylor and Geraldine Taylor, Hudson Taylor in Early Years (1911)', text = 'Had I a thousand pounds China should have it. Had I a thousand lives China should claim every one.', verified = true WHERE figure_id = 82 AND text = 'If I had a thousand pounds, China should have it. If I had a thousand lives, China should have them.';
UPDATE quotes SET source = 'George Washington Carver: In His Own Words (1987)', text = 'It is not the style of clothes one wears, neither the kind of automobiles one drives, nor the amount of money one has in the bank that counts. These mean nothing. It is simply service that measures success.', verified = true WHERE figure_id = 73 AND text = 'It is simply service that measures success.';
UPDATE quotes SET source = 'Sermon on the Third Sunday after Trinity (1528)', text = 'You should not believe your conscience and your feelings more than the word which the Lord who receives sinners preaches to you.', verified = true WHERE figure_id = 1 AND text = 'You should not believe your conscience and your feelings more than the word which the Lord who receives sinners preaches to you.';
UPDATE quotes SET source = 'Feathers for Arrows (1870)', text = 'Prayer pulls the rope below and the great bell rings above in the ears of God. Some scarcely stir the bell, for they pray so languidly; others give but an occasional pluck at the rope; but he who wins with heaven is the man who grasps the rope boldly and pulls continuously, with all his might.', verified = true WHERE figure_id = 4 AND text = 'Prayer pulls the rope down below and the great bell rings above in the ears of God.';
UPDATE quotes SET source = 'The Salt-Cellars (1889)', text = 'By perseverance the snail reached the ark. No doubt the snails started early, and by keeping on they entered the ark, and were saved as surely as the greyhounds.', verified = true WHERE figure_id = 4 AND text = 'By perseverance the snail reached the ark.';
UPDATE quotes SET source = 'Letter to Samuel Furly (1762)', text = 'The longer I live the larger allowances I make for human infirmities. I exact more from myself and less from others.', verified = true WHERE figure_id = 5 AND text = 'The longer I live, the larger allowances I make for human infirmities.';
UPDATE quotes SET source = 'The True Nature of a Gospel Church, Chapter V (1689)', text = '…a man preacheth that sermon only well unto others which preacheth itself in his own soul. And he that doth not feed on and thrive in the digestion of the food which he provides for others will scarce make it savoury unto them.', verified = true WHERE figure_id = 14 AND text = 'A man preacheth that sermon only well unto others which preacheth itself in his own soul.';
UPDATE quotes SET source = 'Letter to Catalina of Jesus (1581)', text = 'God has worked it all for good; for in truth to be abandoned by creatures serves as a file to free us from the fetters of earth, and to suffer darkness is the direct way to the enjoyment of great light.', verified = true WHERE figure_id = 29 AND text = 'The endurance of darkness is preparation for great light.';
UPDATE quotes SET source = 'No One Can Harm the Man Who Does Not Harm Himself, Section 12 (circa 406 AD)', text = '…no one injures a man who does not injure himself. … no trial can agitate the man who does not betray himself.', verified = true WHERE figure_id = 38 AND text = 'No one can harm the man who does not injure himself.';
UPDATE quotes SET source = 'Fragments from the Lost Writings of Irenaeus, Fragment 11 (2nd century AD)', text = 'The business of the Christian is nothing else than to be ever preparing for death.', verified = true WHERE figure_id = 42 AND text = 'The business of the Christian is nothing else but to be ever preparing for death.';
UPDATE quotes SET source = 'Letter 125 to Rusticus, Chapter 11 (411 AD)', text = 'Direct both body and mind to the Lord, overcome wrath by patience, love the knowledge of scripture, and you will no longer love the sins of the flesh.', verified = true WHERE figure_id = 49 AND text = 'Love the knowledge of Scripture, and you will not love the vices of the flesh.';
UPDATE quotes SET source = 'Cited in Sarah Bradford, Harriet, the Moses of Her People (1901)', text = 'I was de conductor ob de Underground Railroad for eight years, an'' I can say what mos'' conductors can''t say—I nebber run my train off de track an'' I nebber los'' a passenger.', verified = true WHERE figure_id = 53 AND text = 'I was the conductor of the Underground Railroad for eight years, and I can say what most conductors can''t say — I never ran my train off the track.';
UPDATE quotes SET source = 'The Anti-Slavery Movement (1855)', text = 'I would unite with anybody to do right; and with nobody to do wrong.', verified = true WHERE figure_id = 56 AND text = 'I would unite with anybody to do right and with nobody to do wrong.';
UPDATE quotes SET source = 'Introduction to the Book of Job (1907)', text = 'The riddles of God are more satisfying than the solutions of man.', verified = true WHERE figure_id = 69 AND text = 'The riddles of God are more satisfying than the solutions of man.';
UPDATE quotes SET source = 'Where There Is Love, There Is God (2010)', text = 'Today, if we have no peace, it is because we have forgotten that we belong to each other—that man, that woman, that child is my brother, my sister.', verified = true WHERE figure_id = 81 AND text = 'If we have no peace, it is because we have forgotten that we belong to each other.';
UPDATE quotes SET source = 'Life in the Spirit (1983)', text = 'We need to find God and he cannot be found in noise and restlessness.', verified = true WHERE figure_id = 81 AND text = 'We need to find God, and he cannot be found in noise and restlessness. God is the friend of silence.';
UPDATE quotes SET source = 'The Pursuit of God (1948)', text = 'The man who has God for his treasure has all things in One.', verified = true WHERE figure_id = 19 AND text = 'The man who has God for his treasure has all things in one.';
UPDATE quotes SET source = 'Cited in Helen M. Roberts, Champion of the Silent Billion (1961)', text = 'The trouble with nearly everybody who prays is that he says ''Amen'' and runs away before God has a chance to reply.', verified = true WHERE figure_id = 96 AND text = 'The trouble with nearly everybody who prays is that he says ''Amen'' and runs away before God has a chance to reply.';
UPDATE quotes SET source = 'Cited in Allister Sparks and Mpho Tutu, Tutu: The Authorised Portrait (2011)', text = 'Do your little bit of good where you are; it''s those little bits of good put together that overwhelm the world.', verified = true WHERE figure_id = 55 AND text = 'Do your little bit of good where you are; it''s those little bits of good put together that overwhelm the world.';
UPDATE quotes SET source = 'Cited in T.C. Hansard, The Parliamentary History of England, vol. 29 (1817)', text = 'Never, never will we desist till we have wiped away this scandal from the Christian name, released ourselves from the load of guilt, under which we at present labour, and extinguished every trace of this bloody traffic…', verified = true WHERE figure_id = 52 AND text = 'Never, never will we desist till we have wiped away this scandal from the Christian name, released ourselves from the load of guilt, under which we at present labour, and extinguished every trace of this bloody traffic…';
UPDATE quotes SET source = 'Cited in Ednah Dow Cheney, "Moses," The Freedmen''s Record, vol. 1, no. 3 (1865)', text = 'I prayed to God … to make me strong and able to fight, and that''s what I''ve allers prayed for ever since.', verified = true WHERE figure_id = 53 AND text = 'I prayed to God to make me strong and able to fight and that''s what I''ve allers prayed for ever since.';
UPDATE quotes SET source = 'Cited in David Brewster, Memoirs of the Life, Writings, and Discoveries of Sir Isaac Newton, vol. 2 (1855)', text = 'I do not know what I may appear to the world, but to myself I seem to have been only like a boy playing on the sea-shore, and diverting myself in now and then finding a smoother pebble or a prettier shell than ordinary, whilst the great ocean of truth lay all undiscovered before me.', verified = true WHERE figure_id = 66 AND text = 'I do not know what I may appear to the world; but to myself I seem to have been only like a boy playing on the sea-shore, and diverting myself in now and then finding a smoother pebble or a prettier shell than ordinary, whilst the great ocean of truth lay all undiscovered before me.';
UPDATE quotes SET source = 'On the Providence of God (1530)', text = 'The cup must be drained, therefore, and the battle won by endurance with undaunted soul. You are God''s tool. He wills to wear you out by use, not by idleness. Oh, happy man, whom He calls to His work!', verified = true WHERE figure_id = 11 AND text = 'You are God''s tool. He wills to wear you out by use, not by idleness. Oh, happy man, whom He calls to His work!';

-- Add (299)

-- Reformers, preachers and theologians: restore or correct (5)
UPDATE quotes SET source = 'The Works of the Reverend George Whitefield, Vol. 6, Sermon XXXVIII: The Indwelling of the Spirit, the Common Privilege of All Believers (1771)', text = 'I am willing to go to prison or death for you; but I am not willing to go to heaven without you.', verified = true WHERE figure_id = 9 AND text = 'I am willing to go to prison and to death for you, but I am not willing to come short of you in heaven.';
UPDATE quotes SET source = 'Studies in the Sermon on the Mount, Vol. 1 (1959)', text = 'The glory of the gospel is that when the Church is absolutely different from the world, she invariably attracts it.', verified = true WHERE figure_id = 22 AND text = 'The glory of the gospel is that when the church is absolutely different from the world, she invariably attracts it.';
UPDATE quotes SET source = 'History of the Reformation in Scotland, Book IV, interview with Mary Queen of Scots (1563)', text = 'Without the preaching place, madam, I think few have occasion to be offended at me; and there, madam, I am not master of myself, but must obey him who commands me to speak plain, and to flatter no flesh upon the face of the earth.', verified = true WHERE figure_id = 10 AND text = 'Madam, I am not master of myself, but must obey him who commands me to speak plain, and to flatter no flesh upon the face of the earth.';
UPDATE quotes SET source = 'Sermon on Isaiah 26 (1565)', text = 'This, I say, is the victory of faith, when in the midst of death, throughout the light of God''s word the afflicted see life.', verified = true WHERE figure_id = 10 AND text = 'This, I say, is the victory of faith, when to the midst of death, through the light of God’s word, the afflicted see life.';
UPDATE quotes SET source = 'Scots Confession, Preface (1560)', text = 'And therefore, by the assistance of the mighty Spirit of the same our Lord Jesus…we firmly purpose to abide to the end in the confession of this our faith.', verified = true WHERE figure_id = 10 AND text = 'And therefore, by the assistance of the mighty Spirit of our Lord Jesus, we firmly promise to abide to the end in the Confession of this our Faith.';

-- Reformers, preachers and theologians: add (207)

COMMIT;
