INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 11, 'Commentary on True and False Religion (1525)', 'Love is a sweet thing, but it takes even the most bitter things cheerfully, for nothing is hard to him that loveth. Therefore, though it seems a great and difficult thing to do to your neighbor what you want done to you, it becomes pleasant and very easy if you love.', 'love,service,compassion,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 11 AND text = 'Love is a sweet thing, but it takes even the most bitter things cheerfully, for nothing is hard to him that loveth. Therefore, though it seems a great and difficult thing to do to your neighbor what you want done to you, it becomes pleasant and very easy if you love.');
