INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 17, 'De Regno Christi, Book 2, provision for the poor (1550)', 'For those that haue the goodes of the worlde and see their Brethern lacke, and haue not compassion on theim: the loue of good dothe not dwell in theim, and so also neither the Kingdom of Christe is in theim.', 'compassion,justice,love,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 17 AND text = 'For those that haue the goodes of the worlde and see their Brethern lacke, and haue not compassion on theim: the loue of good dothe not dwell in theim, and so also neither the Kingdom of Christe is in theim.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 17, 'De Regno Christi, Book 2, provision for the poor (1550)', 'Iff any be asshamed to go gladlye to the hole companye and mynysterie off the Deacons, let him declare his pouertie to one of the Deacons: or if he be lothe to do this, then let such as knowe his neade, and godlynes, shewe it to the Deacons, and get necessarie relief for him.', 'compassion,service,community,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 17 AND text = 'Iff any be asshamed to go gladlye to the hole companye and mynysterie off the Deacons, let him declare his pouertie to one of the Deacons: or if he be lothe to do this, then let such as knowe his neade, and godlynes, shewe it to the Deacons, and get necessarie relief for him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 17, 'De Regno Christi, Book 2, Chapter 19 (1550)', 'And though your Majesty be not bound to th imperial laws, yet it is the duty of a Christian King to embrace and follow what ever he knows to be any where piously and justly constituted, and to be honest, just and well-pleasing to his people.', 'justice,authority,integrity,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 17 AND text = 'And though your Majesty be not bound to th imperial laws, yet it is the duty of a Christian King to embrace and follow what ever he knows to be any where piously and justly constituted, and to be honest, just and well-pleasing to his people.');
