INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 94, 'When the Spirit''s Fire Swept Korea (1943)', 'They prayed about four months, and they said the result was that all forgot about being Methodists and Presbyterians; they only realized that they were all one in the Lord Jesus Christ. That was true church union; it was brought about on the knees; it would last; it would glorify the Most High.', 'unity,prayer,peace,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 94 AND text = 'They prayed about four months, and they said the result was that all forgot about being Methodists and Presbyterians; they only realized that they were all one in the Lord Jesus Christ. That was true church union; it was brought about on the knees; it would last; it would glorify the Most High.');
