INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 94, 'When the Spirit''s Fire Swept Korea (1943)', 'It is always so as soon as God gets first place; but, as a rule, the Church, which professes to be Christ’s, will not cease her busy round of activities and give God a chance by waiting upon Him in prayer.', 'prayer,patience,devotion,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 94 AND text = 'It is always so as soon as God gets first place; but, as a rule, the Church, which professes to be Christ’s, will not cease her busy round of activities and give God a chance by waiting upon Him in prayer.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 5 (2020)', 'At the heart of the Christian message is the death of Jesus Christ on a cross just outside Jerusalem. The question at once arises: if he is God incarnate, what was he doing on a cross? Well, it at the very least means that God has not remained distant from human pain and suffering but has himself experienced it.', 'suffering,hope,faith,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'At the heart of the Christian message is the death of Jesus Christ on a cross just outside Jerusalem. The question at once arises: if he is God incarnate, what was he doing on a cross? Well, it at the very least means that God has not remained distant from human pain and suffering but has himself experienced it.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 6 (2020)', '…we should be looking for how we might love others, even at cost to ourselves—for that is how God has loved every Christian in the person of his Son, by dying for them on the cross.', 'love,service,compassion,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = '…we should be looking for how we might love others, even at cost to ourselves—for that is how God has loved every Christian in the person of his Son, by dying for them on the cross.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 5 (2020)', 'But hope is found in another corona: the crown of thorns that was forced on Jesus'' head at his trial before his execution. That corona shows us just how deep the break between creature and Creator goes.', 'hope,suffering,grace,redemption', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'But hope is found in another corona: the crown of thorns that was forced on Jesus'' head at his trial before his execution. That corona shows us just how deep the break between creature and Creator goes.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Where Is God in a Coronavirus World?, Chapter 2 (2020)', 'We all wish to have intellectual clarity, and many people will spend hours watching news programmes and trawling the internet in the hope of gleaning some new piece of information that may help them understand what is happening. However, intellectual analysis does not easily penetrate a veil of tears.', 'suffering,compassion,truth,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'We all wish to have intellectual clarity, and many people will spend hours watching news programmes and trawling the internet in the hope of gleaning some new piece of information that may help them understand what is happening. However, intellectual analysis does not easily penetrate a veil of tears.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'God''s Undertaker: Has Science Buried God?, Chapter 4 (2007)', 'The more we get to know about our universe, the more the hypothesis that there is a Creator God, who designed the universe for a purpose, gains in credibility as the best explanation of why we are here.', 'creation,faith,truth,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'The more we get to know about our universe, the more the hypothesis that there is a Creator God, who designed the universe for a purpose, gains in credibility as the best explanation of why we are here.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'God''s Undertaker: Has Science Buried God?, Epilogue (2007)', 'But if there is a Mind behind the universe, and if that Mind intends us to be here, the really big question is: Why are we here? What is the purpose of our existence? It is this question above all that exercises the human heart.', 'purpose,creation,truth,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'But if there is a Mind behind the universe, and if that Mind intends us to be here, the really big question is: Why are we here? What is the purpose of our existence? It is this question above all that exercises the human heart.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'God''s Undertaker: Has Science Buried God?, Epilogue (2007)', 'It is no abstraction, or even impersonal force, that lies behind the universe. God, the Creator, is a person.', 'creation,faith,truth,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'It is no abstraction, or even impersonal force, that lies behind the universe. God, the Creator, is a person.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Gunning for God, Chapter 5 (2011)', 'For me, this is the beginning of hope; and it is a living hope that cannot be smashed by the enemy of death. The story does not end in the darkness of the cross.', 'hope,suffering,resurrection,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'For me, this is the beginning of hope; and it is a living hope that cannot be smashed by the enemy of death. The story does not end in the darkness of the cross.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Gunning for God, Chapter 5 (2011)', 'On the other hand, atheism has got rid of hope; yet I as a Christian have hope, even in the face of suffering and evil. … Human conscience and desire for justice are not a delusion.', 'hope,justice,suffering,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'On the other hand, atheism has got rid of hope; yet I as a Christian have hope, even in the face of suffering and evil. … Human conscience and desire for justice are not a delusion.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Gunning for God, Chapter 5 (2011)', 'However, I believe that death is not the end, and that God is a God of compensation. The resurrection of Jesus Christ demonstrates that there is to be a final assessment at which God will not only be just, but will also be seen to be just.', 'resurrection,justice,hope,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'However, I believe that death is not the end, and that God is a God of compensation. The resurrection of Jesus Christ demonstrates that there is to be a final assessment at which God will not only be just, but will also be seen to be just.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Can Science Explain Everything?, Chapter 2 (2019)', 'The God of the Bible is not a god of the gaps. He is the God of the whole show. He is the God of the bits of the universe we don''t understand and the bits we do.', 'creation,sovereignty,faith,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'The God of the Bible is not a god of the gaps. He is the God of the whole show. He is the God of the bits of the universe we don''t understand and the bits we do.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Can Science Explain Everything?, Chapter 9 (2019)', 'It says that, if they will, anyone can be forgiven and find a new life and friendship with God—whoever they are; whatever they have done.', 'grace,forgiveness,hope,redemption', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'It says that, if they will, anyone can be forgiven and find a new life and friendship with God—whoever they are; whatever they have done.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Seven Days That Divide the World, Chapter 5 (2011)', 'All of us long for rest. Not simply the taking of a regular day of rest and recuperation, or going on a much-needed holiday, but respite from the constant pressure to achieve. … We are restless beings.', 'rest,peace,work,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'All of us long for rest. Not simply the taking of a regular day of rest and recuperation, or going on a much-needed holiday, but respite from the constant pressure to achieve. … We are restless beings.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 80, 'Seven Days That Divide the World, Chapter 5 (2011)', 'God is not some distant deistic figure uninterested in his work. He regards his creation with the enthusiasm and joy of a skilful artist who is delighted at what he has done…', 'creation,joy,providence,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 80 AND text = 'God is not some distant deistic figure uninterested in his work. He regards his creation with the enthusiasm and joy of a skilful artist who is delighted at what he has done…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 1, Jesus—An Interpretation (1949)', 'The basic fact is that Christianity as it was born in the mind of this Jewish teacher and thinker appears as a technique of survival for the oppressed.', 'justice,hope,faith,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'The basic fact is that Christianity as it was born in the mind of this Jewish teacher and thinker appears as a technique of survival for the oppressed.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 2, Fear (1949)', 'The awareness of being a child of God tends to stabilize the ego and results in a new courage, fearlessness, and power.', 'courage,faith,identity,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'The awareness of being a child of God tends to stabilize the ego and results in a new courage, fearlessness, and power.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 2, Fear (1949)', 'Such a man recognizes that death cannot possibly be the worst thing in the world. There are some things that are worse than death. To deny one’s own integrity of personality in the presence of the human challenge is one of those things.', 'courage,integrity,truth,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Such a man recognizes that death cannot possibly be the worst thing in the world. There are some things that are worse than death. To deny one’s own integrity of personality in the presence of the human challenge is one of those things.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 3, Deception (1949)', 'The penalty of deception is to become a deception, with all sense of moral discrimination vitiated. A man who lies habitually becomes a lie, and it is increasingly impossible for him to know when he is lying and when he is not.', 'truth,integrity,humility,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'The penalty of deception is to become a deception, with all sense of moral discrimination vitiated. A man who lies habitually becomes a lie, and it is increasingly impossible for him to know when he is lying and when he is not.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Chapter 4, Hate (1949)', 'Jesus rejected hatred. It was not because he lacked the vitality or the strength. It was not because he lacked the incentive. … He affirmed life; and hatred was the great denial.', 'love,peace,courage,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Jesus rejected hatred. It was not because he lacked the vitality or the strength. It was not because he lacked the incentive. … He affirmed life; and hatred was the great denial.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Jesus and the Disinherited, Epilogue (1949)', 'Thus interpreted, he belongs to no age, no race, no creed. When men look into his face, they see etched the glory of their own possibilities, and their hearts whisper, “Thank you and thank God!”', 'hope,faith,gratitude,christ', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Thus interpreted, he belongs to no age, no race, no creed. When men look into his face, they see etched the glory of their own possibilities, and their hearts whisper, “Thank you and thank God!”');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, Keep Alive the Dream in the Heart (1953)', 'Keep alive the dream; for as long as a man has a dream in his heart, he cannot lose the significance of living.', 'hope,perseverance,purpose,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Keep alive the dream; for as long as a man has a dream in his heart, he cannot lose the significance of living.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, Lord, Lord, Open Unto Me (1953)', 'Open unto me—light for my darkness. Open unto me—courage for my fear. Open unto me—hope for my despair. Open unto me—peace for my turmoil.', 'prayer,hope,courage,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Open unto me—light for my darkness. Open unto me—courage for my fear. Open unto me—hope for my despair. Open unto me—peace for my turmoil.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, How Good to Center Down! (1953)', 'How good it is to center down! To sit quietly and see one’s self pass by! The streets of our minds seethe with endless traffic; Our spirits resound with clashings, with noisy silences, While something deep within hungers and thirsts for the still moment and the resting lull.', 'prayer,peace,rest,contemplation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'How good it is to center down! To sit quietly and see one’s self pass by! The streets of our minds seethe with endless traffic; Our spirits resound with clashings, with noisy silences, While something deep within hungers and thirsts for the still moment and the resting lull.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'Meditations of the Heart, The Growing Edge (1953)', 'Look well to the growing edge. All around us worlds are dying and new worlds are being born; all around us life is dying and life is being born. The fruit ripens on the tree, the roots are silently at work in the darkness of the earth against a time when there shall be new leaves, fresh blossoms, green fruit.', 'hope,creation,perseverance,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'Look well to the growing edge. All around us worlds are dying and new worlds are being born; all around us life is dying and life is being born. The fruit ripens on the tree, the roots are silently at work in the darkness of the earth against a time when there shall be new leaves, fresh blossoms, green fruit.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'The Inward Journey, A Strange Freedom (1961)', 'It is a strange freedom to be adrift in the world of men without a sense of anchor anywhere. Always there is the need of mooring, the need for the firm grip on something that is rooted and will not give.', 'freedom,faith,longing,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = 'It is a strange freedom to be adrift in the world of men without a sense of anchor anywhere. Always there is the need of mooring, the need for the firm grip on something that is rooted and will not give.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 64, 'The Search for Common Ground (1971)', '…community cannot feed for long on itself; it can only flourish where always the boundaries are giving way to the coming of others from beyond them—unknown and undiscovered brothers.', 'community,unity,love,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 64 AND text = '…community cannot feed for long on itself; it can only flourish where always the boundaries are giving way to the coming of others from beyond them—unknown and undiscovered brothers.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Dream with Me (2017)', 'God’s love and justice come together in the redemptive work of Jesus Christ, and we can’t be about one and not the other.', 'justice,love,gospel,reconciliation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'God’s love and justice come together in the redemptive work of Jesus Christ, and we can’t be about one and not the other.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Dream with Me (2017)', 'Justice is a process, and change takes time, but I believe we ought to dream big dreams and make big statements as we pursue those dreams.', 'justice,hope,perseverance,patience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'Justice is a process, and change takes time, but I believe we ought to dream big dreams and make big statements as we pursue those dreams.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Dream with Me (2017)', 'We are called to love. To love God, to love our neighbors, even to love our enemies. Yes, love can be a real struggle. Anger is easier.', 'love,discipleship,forgiveness,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'We are called to love. To love God, to love our neighbors, even to love our enemies. Yes, love can be a real struggle. Anger is easier.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Dream with Me (2017)', 'The fact that we ought to forgive others is a burden. The fact that we can forgive others is a blessing.', 'forgiveness,grace,love,reconciliation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'The fact that we ought to forgive others is a burden. The fact that we can forgive others is a blessing.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Dream with Me (2017)', 'The second R—reconciliation—is the heart of the gospel. It is the process by which God brings us to Him and keeps us.', 'reconciliation,gospel,grace,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'The second R—reconciliation—is the heart of the gospel. It is the process by which God brings us to Him and keeps us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Dream with Me (2017)', 'Reconciliation is working in the process of forgiveness—being forgiven and forgiving others. It’s an ongoing, living thing in the Bible. It’s active. It’s a moving force.', 'reconciliation,forgiveness,grace,transformation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'Reconciliation is working in the process of forgiveness—being forgiven and forgiving others. It’s an ongoing, living thing in the Bible. It’s active. It’s a moving force.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Let Justice Roll Down (1976)', 'Yet God loved these young men no less than He loved me. So if God had done all this for me, and if He loved these others no less than He did me, what did all this mean?', 'love,grace,calling,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'Yet God loved these young men no less than He loved me. So if God had done all this for me, and if He loved these others no less than He did me, what did all this mean?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Let Justice Roll Down (1976)', 'The Spirit of God worked on me as I lay in that bed. An image formed in my mind. The image of the cross—Christ on the cross. It blotted out everything else in my mind. This Jesus knew what I had suffered. He understood. And He cared.', 'suffering,cross,comfort,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'The Spirit of God worked on me as I lay in that bed. An image formed in my mind. The image of the cross—Christ on the cross. It blotted out everything else in my mind. This Jesus knew what I had suffered. He understood. And He cared.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Let Justice Roll Down (1976)', 'When I saw what hate had done to them, I couldn''t hate back. I could only pity them. I didn''t ever want hate to do to me what it had already done to those men.', 'love,forgiveness,compassion,moral_courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'When I saw what hate had done to them, I couldn''t hate back. I could only pity them. I didn''t ever want hate to do to me what it had already done to those men.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Let Justice Roll Down (1976)', 'This is my hope, a healing hope: that this book might be one small part of that process of reconciling people together through the real searching of our souls.', 'hope,reconciliation,repentance,unity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'This is my hope, a healing hope: that this book might be one small part of that process of reconciling people together through the real searching of our souls.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'With Justice for All (1982)', 'The earth does not belong to you and me, but to God. We are only its stewards. God provided the earth for all mankind.', 'stewardship,justice,creation,generosity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'The earth does not belong to you and me, but to God. We are only its stewards. God provided the earth for all mankind.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'With Justice for All (1982)', '…a gospel that reconciles black and white, for unless we preach a gospel of reconciliation we preach no gospel at all.', 'reconciliation,gospel,unity,preaching', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = '…a gospel that reconciles black and white, for unless we preach a gospel of reconciliation we preach no gospel at all.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 65, 'Beyond Charity (1993)', 'We do not confer dignity upon other human beings. God has already given dignity to us when he created us. We are his personal handiwork; what greater source of dignity could we have?', 'dignity,creation,justice,humanity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 65 AND text = 'We do not confer dignity upon other human beings. God has already given dignity to us when he created us. We are his personal handiwork; what greater source of dignity could we have?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'The Freedom of a Christian (1520)', 'We conclude therefore that a Christian man does not live in himself, but in Christ and in his neighbour, or else is no Christian: in Christ by faith; in his neighbour by love. By faith he is carried upwards above himself to God, and by love he sinks back below himself to his neighbour…', 'love,faith,neighbor_love,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'We conclude therefore that a Christian man does not live in himself, but in Christ and in his neighbour, or else is no Christian: in Christ by faith; in his neighbour by love. By faith he is carried upwards above himself to God, and by love he sinks back below himself to his neighbour…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'The Freedom of a Christian (1520)', 'And as our heavenly Father has freely helped us in Christ, so ought we freely to help our neighbour by our body and works, and each should become to other a sort of Christ, so that we may be mutually Christs, and that the same Christ may be in all of us; that is, that we may be truly Christians.', 'service,compassion,neighbor_love,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'And as our heavenly Father has freely helped us in Christ, so ought we freely to help our neighbour by our body and works, and each should become to other a sort of Christ, so that we may be mutually Christs, and that the same Christ may be in all of us; that is, that we may be truly Christians.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'The Freedom of a Christian (1520)', 'Thus from faith flow forth love and joy in the Lord, and from love a cheerful, willing, free spirit, disposed to serve our neighbour voluntarily, without taking any account of gratitude or ingratitude, praise or blame, gain or loss.', 'joy,service,love,freedom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'Thus from faith flow forth love and joy in the Lord, and from love a cheerful, willing, free spirit, disposed to serve our neighbour voluntarily, without taking any account of gratitude or ingratitude, praise or blame, gain or loss.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Large Catechism, Fifth Commandment (1529)', 'If, therefore, you send away one that is naked when you could clothe him, you have caused him to freeze to death; you see one suffer hunger and do not give him food, you have caused him to starve. So also, if you see any one innocently sentenced to death or in like distress, and do not save him, although you know ways and means to do so, you have killed him.', 'justice,compassion,neighbor_love,responsibility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'If, therefore, you send away one that is naked when you could clothe him, you have caused him to freeze to death; you see one suffer hunger and do not give him food, you have caused him to starve. So also, if you see any one innocently sentenced to death or in like distress, and do not save him, although you know ways and means to do so, you have killed him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Large Catechism, Lord''s Prayer, Fifth Petition (1529)', 'For just as we daily sin much against God and yet He forgives everything through grace, so we, too, must ever forgive our neighbor who does us injury, violence, and wrong…', 'forgiveness,grace,neighbor_love,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'For just as we daily sin much against God and yet He forgives everything through grace, so we, too, must ever forgive our neighbor who does us injury, violence, and wrong…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Table Talk, Of Prayer (1566)', 'It is a great matter when in extreme need, as then one can take hold on prayer. I know, as often as I have earnestly prayed, that I have been richly heard, and have obtained more than I prayed for; indeed, God sometimes deferred, but notwithstanding he came.', 'prayer,hope,faith,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'It is a great matter when in extreme need, as then one can take hold on prayer. I know, as often as I have earnestly prayed, that I have been richly heard, and have obtained more than I prayed for; indeed, God sometimes deferred, but notwithstanding he came.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Table Talk (1566)', 'But certainly it must be better one day; it cannot always so remain; let us have but patience, and steadfastly remain by the pure doctrine, and, notwithstanding all this misery, let us not fall away from the same.', 'hope,patience,perseverance,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'But certainly it must be better one day; it cannot always so remain; let us have but patience, and steadfastly remain by the pure doctrine, and, notwithstanding all this misery, let us not fall away from the same.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Table Talk (1566)', 'Believest thou? then thou wilt speak boldly. Speakest thou boldly? then thou must suffer. Sufferest thou? then thou shalt be comforted.', 'courage,faith,suffering,comfort', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'Believest thou? then thou wilt speak boldly. Speakest thou boldly? then thou must suffer. Sufferest thou? then thou shalt be comforted.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Treatise on Good Works, Second Commandment (1520)', 'For the greater portion of the powerful, rich and friends do injustice and oppress the poor, the lowly, and their own opponents; and the greater the men, the worse the deeds; and where we cannot by force prevent it and help the truth, we should at least confess it, and do what we can with words, not take the part of the unrighteous, not approve them, but speak the truth boldly.', 'justice,truth,moral_courage,poverty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'For the greater portion of the powerful, rich and friends do injustice and oppress the poor, the lowly, and their own opponents; and the greater the men, the worse the deeds; and where we cannot by force prevent it and help the truth, we should at least confess it, and do what we can with words, not take the part of the unrighteous, not approve them, but speak the truth boldly.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 1, 'Treatise on Good Works, Third Commandment (1520)', 'Therefore, however long we live, we shall always have our hands full to remain, with all our works and sufferings, pupils of the First Commandment and of faith, and not to cease to learn. No one knows what a great thing it is to trust God alone, except he who attempts it with his works.', 'trust,faith,perseverance,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 1 AND text = 'Therefore, however long we live, we shall always have our hands full to remain, with all our works and sufferings, pupils of the First Commandment and of faith, and not to cease to learn. No one knows what a great thing it is to trust God alone, except he who attempts it with his works.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Augsburg Confession, Article XXVII (1530)', 'For Christian perfection is to fear God from the heart, and yet to conceive great faith, and to trust that for Christ''s sake we have a God who has been reconciled, to ask of God, and assuredly to expect His aid in all things that, according to our calling, are to be done; and meanwhile, to be diligent in outward good works, and to serve our calling.', 'vocation,faith,trust,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'For Christian perfection is to fear God from the heart, and yet to conceive great faith, and to trust that for Christ''s sake we have a God who has been reconciled, to ask of God, and assuredly to expect His aid in all things that, according to our calling, are to be done; and meanwhile, to be diligent in outward good works, and to serve our calling.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Augsburg Confession, Article XXVI (1530)', 'For they have always taught concerning the cross that it behooves Christians to bear afflictions. This is the true, earnest, and unfeigned mortification, to wit, to be exercised with divers afflictions, and to be crucified with Christ.', 'suffering,discipleship,perseverance,cross', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'For they have always taught concerning the cross that it behooves Christians to bear afflictions. This is the true, earnest, and unfeigned mortification, to wit, to be exercised with divers afflictions, and to be crucified with Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Apology of the Augsburg Confession, Preface (1531)', 'Wherefore we believe that troubles and dangers for the glory of Christ and the good of the Church should be endured, and we are confident that this our fidelity to duty is approved of God, and we hope that the judgment of posterity concerning us will be more just.', 'courage,perseverance,hope,faithfulness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'Wherefore we believe that troubles and dangers for the glory of Christ and the good of the Church should be endured, and we are confident that this our fidelity to duty is approved of God, and we hope that the judgment of posterity concerning us will be more just.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Apology of the Augsburg Confession, Article III, Of Love and the Fulfilling of the Law (1531)', 'Nor would it be possible that a saint, great and high though he be, could make a firm stand against the accusations of the divine Law, the great might of the devil, the terror of death, and, finally, against despair and the anguish of hell, if he would not grasp the divine promises, the Gospel, as a tree or branch in the great flood in the strong, violent stream, amidst the waves and billows of the anguish of death…', 'hope,faith,suffering,scripture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'Nor would it be possible that a saint, great and high though he be, could make a firm stand against the accusations of the divine Law, the great might of the devil, the terror of death, and, finally, against despair and the anguish of hell, if he would not grasp the divine promises, the Gospel, as a tree or branch in the great flood in the strong, violent stream, amidst the waves and billows of the anguish of death…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Apology of the Augsburg Confession, Article III, Of Love and the Fulfilling of the Law (1531)', 'And throughout our entire life we are to pray God and be diligent, to receive faith and to grow in faith. … This faith is to grow and increase throughout our life by all manner of afflictions.', 'faith,prayer,perseverance,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'And throughout our entire life we are to pray God and be diligent, to receive faith and to grow in faith. … This faith is to grow and increase throughout our life by all manner of afflictions.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Cited in Charles Frederick Ledderhose, The Life of Philip Melanchthon (1855)', 'Let us be assured that God will preserve the seed of his Church and of the truth, as he has so repeatedly promised in his divine word, and let us not doubt that God has our welfare at heart, even if the world should be destroyed.', 'hope,providence,church,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'Let us be assured that God will preserve the seed of his Church and of the truth, as he has so repeatedly promised in his divine word, and let us not doubt that God has our welfare at heart, even if the world should be destroyed.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 12, 'Cited in Charles Frederick Ledderhose, The Life of Philip Melanchthon (1855)', 'We pray God that he will not permit you to sink in this great distress, but would by his Holy Spirit grant you comfort and strength, as he has often promised that he is a God who dwelleth with the sorrowful, as I have often experienced in no slight afflictions.', 'comfort,prayer,suffering,compassion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 12 AND text = 'We pray God that he will not permit you to sink in this great distress, but would by his Holy Spirit grant you comfort and strength, as he has often promised that he is a God who dwelleth with the sorrowful, as I have often experienced in no slight afflictions.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 16, To the People of Prague, October 1412 (1904)', 'Let us then consider these matters and give the preference to the truth and to the promise of God. Let us live nobly in love and resist the lie of Antichrist to the end. Let us make the Saviour Almighty our Helper, Whom no man can overcome, and Who will never forsake us so long as we ourselves do not forsake Him.', 'truth,love,courage,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'Let us then consider these matters and give the preference to the truth and to the promise of God. Let us live nobly in love and resist the lie of Antichrist to the end. Let us make the Saviour Almighty our Helper, Whom no man can overcome, and Who will never forsake us so long as we ourselves do not forsake Him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 39, To the Faithful Bohemians, Constance, 16 November 1414 (1904)', 'Wherefore I entreat you to pray God earnestly that it may please Him to furnish me with wisdom, patience, humility, and energy, in order to stand firm in His truth. … Yet I trust to the mercy of the Saviour and to your prayers that I shall stand firm in God''s truth unto death.', 'prayer,courage,truth,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'Wherefore I entreat you to pray God earnestly that it may please Him to furnish me with wisdom, patience, humility, and energy, in order to stand firm in His truth. … Yet I trust to the mercy of the Saviour and to your prayers that I shall stand firm in God''s truth unto death.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 47, To John of Chlum, February 1415 (1904)', 'God, most gracious, at one time consoles me and at another afflicts me; but I trust He is ever with me in tribulation.', 'suffering,trust,comfort,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'God, most gracious, at one time consoles me and at another afflicts me; but I trust He is ever with me in tribulation.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 64, To All the People of Bohemia, 10 June 1415 (1904)', 'I write this letter to you in prison, bound with chains and expecting on the morrow the sentence of death, yet fully trusting in God that I shall not swerve from His truth nor swear denial of the errors, whereof I have been charged by false witnesses.', 'courage,truth,martyrdom,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'I write this letter to you in prison, bound with chains and expecting on the morrow the sentence of death, yet fully trusting in God that I shall not swerve from His truth nor swear denial of the errors, whereof I have been charged by false witnesses.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 65, To Henry Skopek de Duba, 13 June 1415 (1904)', 'I cannot write at length; but in a few words I counsel you to keep in your heart God''s counsels, to be kind to the poor, to abstain from pride, to lead a chaste life…', 'compassion,humility,holiness,poverty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'I cannot write at length; but in a few words I counsel you to keep in your heart God''s counsels, to be kind to the poor, to abstain from pride, to lead a chaste life…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 74, To the Faithful Bohemians, 24 June 1415 (1904)', 'I am trusting that God will raise up others after me, braver men than there are to-day, who shall… lay down their lives for the truth of the Lord Jesus Christ, who will grant eternal joy both to you and to me.', 'hope,courage,truth,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'I am trusting that God will raise up others after me, braver men than there are to-day, who shall… lay down their lives for the truth of the Lord Jesus Christ, who will grant eternal joy both to you and to me.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 20, 'The Letters of John Hus, Letter 78, To the University of Prague, 27 June 1415 (1904)', 'I exhort you in the name of the blessed Jesus to love one another, to root out schisms and to promote the honour of God before all things.', 'unity,love,peace,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 20 AND text = 'I exhort you in the name of the blessed Jesus to love one another, to root out schisms and to promote the honour of God before all things.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, I.5.1 (1559)', 'His essence, indeed, is incomprehensible, utterly transcending all human thought; but on each of his works his glory is engraven in characters so bright, so distinct, and so illustrious, that none, however dull and illiterate, can plead ignorance as their excuse.', 'creation,glory,wonder,knowledge_of_god', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = 'His essence, indeed, is incomprehensible, utterly transcending all human thought; but on each of his works his glory is engraven in characters so bright, so distinct, and so illustrious, that none, however dull and illiterate, can plead ignorance as their excuse.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, I.14.20 (1559)', 'Meanwhile, being placed in this most beautiful theatre, let us not decline to take a pious delight in the clear and manifest works of God.', 'creation,joy,gratitude,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = 'Meanwhile, being placed in this most beautiful theatre, let us not decline to take a pious delight in the clear and manifest works of God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, I.17.11 (1559)', '…ignorance of Providence is the greatest of all miseries, and the knowledge of it the highest happiness.', 'providence,peace,trust,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = '…ignorance of Providence is the greatest of all miseries, and the knowledge of it the highest happiness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, III.7.6 (1559)', '…we are not to look to what men in themselves deserve, but to attend to the image of God, which exists in all, and to which we owe all honour and love.', 'love,compassion,human_dignity,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = '…we are not to look to what men in themselves deserve, but to attend to the image of God, which exists in all, and to which we owe all honour and love.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, III.8.1 (1559)', 'How powerfully should it soften the bitterness of the cross, to think that the more we are afflicted with adversity, the surer we are made of our fellowship with Christ; by communion with whom our sufferings are not only blessed to us, but tend greatly to the furtherance of our salvation.', 'suffering,hope,perseverance,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = 'How powerfully should it soften the bitterness of the cross, to think that the more we are afflicted with adversity, the surer we are made of our fellowship with Christ; by communion with whom our sufferings are not only blessed to us, but tend greatly to the furtherance of our salvation.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, III.10.6 (1559)', 'This, too, will afford admirable consolation, that in following your proper calling, no work will be so mean and sordid as not to have a splendour and value in the eye of God.', 'work,calling,service,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = 'This, too, will afford admirable consolation, that in following your proper calling, no work will be so mean and sordid as not to have a splendour and value in the eye of God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, III.18.6 (1559)', '…if we think that heaven is our country, we should send our wealth thither rather than retain it here, where on our sudden departure it will be lost to us. But how shall we transmit it? By contributing to the necessities of the poor, the Lord imputing to himself whatever is given to them.', 'generosity,compassion,hope,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = '…if we think that heaven is our country, we should send our wealth thither rather than retain it here, where on our sudden departure it will be lost to us. But how shall we transmit it? By contributing to the necessities of the poor, the Lord imputing to himself whatever is given to them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Institutes of the Christian Religion, III.20.2 (1559)', '…so true it is that prayer digs up those treasures which the Gospel of our Lord discovers to the eye of faith. The necessity and utility of this exercise of prayer no words can sufficiently express.', 'prayer,faith,grace,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = '…so true it is that prayer digs up those treasures which the Gospel of our Lord discovers to the eye of faith. The necessity and utility of this exercise of prayer no words can sufficiently express.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Commentary on Romans, 8:28 (1540)', '…though God does not immediately succour his people, he yet does not forsake them, for by a wonderful contrivance he turns those things which seem to be evils in such a way as to promote their salvation.', 'providence,suffering,hope,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = '…though God does not immediately succour his people, he yet does not forsake them, for by a wonderful contrivance he turns those things which seem to be evils in such a way as to promote their salvation.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Commentary on Romans, 12:12 (1540)', 'If our joy is derived from the hope of future life, then patience will grow up in adversities; for no kind of sorrow will be able to overwhelm this joy.', 'joy,hope,perseverance,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = 'If our joy is derived from the hope of future life, then patience will grow up in adversities; for no kind of sorrow will be able to overwhelm this joy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 2, 'Commentary on Romans, 12:14 (1540)', '…we are not to imprecate evils on our enemies, but to wish and to pray God to render all things prosperous to them, how much soever they may harass and cruelly treat us.', 'love_of_enemies,prayer,forgiveness,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 2 AND text = '…we are not to imprecate evils on our enemies, but to wish and to pray God to render all things prosperous to them, how much soever they may harass and cruelly treat us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'With Christ in the School of Prayer, Lesson 1 (1885)', 'Not only for ourselves, but for others, for the Church, for the world, it is to prayer that God has given the right to take hold of Him and His strength. It is on prayer that the promises wait for their fulfilment, the kingdom for its coming, the glory of God for its full revelation.', 'prayer,hope,faith,mission', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'Not only for ourselves, but for others, for the Church, for the world, it is to prayer that God has given the right to take hold of Him and His strength. It is on prayer that the promises wait for their fulfilment, the kingdom for its coming, the glory of God for its full revelation.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'With Christ in the School of Prayer, Preface (1885)', 'It is my prayer that God may use this little book to make clearer to some of His children the wonderful place of power and influence which He is waiting for them to occupy, and for which a weary world is waiting too.', 'prayer,calling,hope,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'It is my prayer that God may use this little book to make clearer to some of His children the wonderful place of power and influence which He is waiting for them to occupy, and for which a weary world is waiting too.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'With Christ in the School of Prayer, Lesson 3 (1885)', 'But to the man who withdraws himself from all that is of the world and man, and prepares to wait upon God alone, the Father will reveal Himself.', 'prayer,solitude,devotion,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'But to the man who withdraws himself from all that is of the world and man, and prepares to wait upon God alone, the Father will reveal Himself.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Abide in Christ, Chapter 25 (1882)', 'With a heart full of joy no work can weary, and no burden can depress; God Himself is strength and song.', 'joy,strength,perseverance,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'With a heart full of joy no work can weary, and no burden can depress; God Himself is strength and song.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Abide in Christ, Chapter 19 (1882)', 'In Him thou seest a thousand times more given thee than thou hast lost; seest how God only took from thee that thou mightest have room to take from Him what is so much better.', 'suffering,comfort,hope,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'In Him thou seest a thousand times more given thee than thou hast lost; seest how God only took from thee that thou mightest have room to take from Him what is so much better.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Humility, Chapter 6 (1895)', 'The humble man feels no jealousy or envy. He can praise God when others are preferred and blessed before him. He can bear to hear others praised and himself forgotten, because in God''s presence he has learnt to say with Paul, ''I am nothing.''', 'humility,love,community,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'The humble man feels no jealousy or envy. He can praise God when others are preferred and blessed before him. He can bear to hear others praised and himself forgotten, because in God''s presence he has learnt to say with Paul, ''I am nothing.''');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Humility, Chapter 1 (1895)', 'Humility is the only soil in which the graces root; the lack of humility is the sufficient explanation of every defect and failure. Humility is not so much a grace or virtue along with others; it is the root of all, because it alone takes the right attitude before God, and allows Him as God to do all.', 'humility,grace,faith,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'Humility is the only soil in which the graces root; the lack of humility is the sufficient explanation of every defect and failure. Humility is not so much a grace or virtue along with others; it is the root of all, because it alone takes the right attitude before God, and allows Him as God to do all.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'The Ministry of Intercession, Chapter 14 (1897)', 'There is a world, with its needs entirely dependent on and waiting to be helped by intercession; there is a God in heaven, with His all-sufficient supply for all those needs, waiting to be asked; there is a Church, with its wondrous calling and its sure promises, waiting to be roused to a sense of its wondrous responsibility and power.', 'prayer,intercession,hope,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'There is a world, with its needs entirely dependent on and waiting to be helped by intercession; there is a God in heaven, with His all-sufficient supply for all those needs, waiting to be asked; there is a Church, with its wondrous calling and its sure promises, waiting to be roused to a sense of its wondrous responsibility and power.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'The Ministry of Intercession, Chapter 4 (1897)', 'It is as men live that they pray. It is the life that prays. It is the life that, with whole-hearted devotion, gives up all for God and to God, that can claim all from God.', 'prayer,devotion,surrender,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'It is as men live that they pray. It is the life that prays. It is the life that, with whole-hearted devotion, gives up all for God and to God, that can claim all from God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Waiting on God, Day 10 (1896)', 'For the dangers are often very real and dark; the situation, whether in the temporal or spiritual life, may appear to be utterly hopeless; there is always one hope: God''s eye is on them.', 'hope,trust,providence,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'For the dangers are often very real and dark; the situation, whether in the temporal or spiritual life, may appear to be utterly hopeless; there is always one hope: God''s eye is on them.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Waiting on God, Day 11 (1896)', 'This patience honors Him greatly; it leaves Him, as God on the throne, to do His work; it yields self wholly into His hands. It lets God be God.', 'patience,trust,sovereignty,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'This patience honors Him greatly; it leaves Him, as God on the throne, to do His work; it yields self wholly into His hands. It lets God be God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Absolute Surrender, The Fruit of the Spirit is Love (1895)', 'It is only when God''s people stand as one body, one before God in the fellowship of love, one toward another in deep affection, one before the world in a love that the world can see—it is only then that they will have power to secure the blessing which they ask of God.', 'love,unity,community,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'It is only when God''s people stand as one body, one before God in the fellowship of love, one toward another in deep affection, one before the world in a love that the world can see—it is only then that they will have power to secure the blessing which they ask of God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Absolute Surrender, The Fruit of the Spirit is Love (1895)', 'Let a man be what he will, you are to love him. Love is to be the fruit of the Spirit all the day and every day.', 'love,compassion,holy_spirit,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'Let a man be what he will, you are to love him. Love is to be the fruit of the Spirit all the day and every day.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Working for God, Chapter 2 (1901)', 'Perishing men around you need your light, if they are to find their way to God. God needs you, to let His glory be seen through you. As wholly as a lamp is given up to lighting a room, every believer ought to give himself up to be the light of a dark world.', 'service,calling,witness,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'Perishing men around you need your light, if they are to find their way to God. God needs you, to let His glory be seen through you. As wholly as a lamp is given up to lighting a room, every believer ought to give himself up to be the light of a dark world.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Working for God, Chapter 4 (1901)', 'Every believer, the feeblest as much as the strongest, has the calling to live and work for the kingdom of his Lord. … Not one can be missed, because the Master gave to every one his work.', 'calling,service,work,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'Every believer, the feeblest as much as the strongest, has the calling to live and work for the kingdom of his Lord. … Not one can be missed, because the Master gave to every one his work.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'The Spirit of Christ, Chapter 12 (1888)', 'It is the life of believers in self-sacrificing love that will prove to the world that Christ is a reality, and so convince it of its sin of unbelief.', 'love,witness,holy_spirit,sacrifice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'It is the life of believers in self-sacrificing love that will prove to the world that Christ is a reality, and so convince it of its sin of unbelief.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 100, 'Holy in Christ, Day 13 (1887)', 'There is nothing that has such an attraction for God, that has such affinity with holiness, as a contrite and humble spirit.', 'humility,holiness,repentance,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 100 AND text = 'There is nothing that has such an attraction for God, that has such affinity with holiness, as a contrite and humble spirit.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Enquiry into the Obligations of Christians to Use Means for the Conversion of the Heathens, Introduction (1792)', 'As our blessed Lord has required us to pray that his kingdom may come, and his will be done on earth as it is in heaven, it becomes us not only to express our desires of that event by words, but to use every lawful method to spread the knowledge of his name.', 'prayer,mission,diligence,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'As our blessed Lord has required us to pray that his kingdom may come, and his will be done on earth as it is in heaven, it becomes us not only to express our desires of that event by words, but to use every lawful method to spread the knowledge of his name.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Enquiry into the Obligations of Christians to Use Means for the Conversion of the Heathens, Section 4 (1792)', '…whoever does go must put his life in his hand, and not consult with flesh and blood; but do not the goodness of the cause, the duties incumbent on us as the creatures of God, and Christians, and the perishing state of our fellow men, loudly call upon us to venture all and use every warrantable exertion for their benefit?', 'courage,mission,sacrifice,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = '…whoever does go must put his life in his hand, and not consult with flesh and blood; but do not the goodness of the cause, the duties incumbent on us as the creatures of God, and Christians, and the perishing state of our fellow men, loudly call upon us to venture all and use every warrantable exertion for their benefit?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Enquiry into the Obligations of Christians to Use Means for the Conversion of the Heathens, Section 4 (1792)', 'A Christian minister is a person who in a peculiar sense is not his own; he is the servant of God, and therefore ought to be wholly devoted to him.', 'service,calling,devotion,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'A Christian minister is a person who in a peculiar sense is not his own; he is the servant of God, and therefore ought to be wholly devoted to him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Enquiry into the Obligations of Christians to Use Means for the Conversion of the Heathens, Section 5 (1792)', 'There is room enough for us all, without interfering with each other; and if no unfriendly interference took place, each denomination would bear good will to the other, and wish, and pray for its success…', 'unity,community,prayer,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'There is room enough for us all, without interfering with each other; and if no unfriendly interference took place, each denomination would bear good will to the other, and wish, and pray for its success…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Enquiry into the Obligations of Christians to Use Means for the Conversion of the Heathens, Section 5 (1792)', 'Many persons have of late left off the use of West-India sugar on account of the iniquitous manner in which it is obtained. … We have only to keep the end in view, and have our hearts thoroughly engaged in the pursuit of it, and means will not be very difficult.', 'justice,diligence,perseverance,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'Many persons have of late left off the use of West-India sugar on account of the iniquitous manner in which it is obtained. … We have only to keep the end in view, and have our hearts thoroughly engaged in the pursuit of it, and means will not be very difficult.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Cited in George Smith, The Life of William Carey, Shoemaker and Missionary (1885)', 'In one short evening… the labours of years are consumed. How unsearchable are the ways of God! … The Lord has laid me low, that I may look more simply to Him.', 'suffering,humility,providence,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'In one short evening… the labours of years are consumed. How unsearchable are the ways of God! … The Lord has laid me low, that I may look more simply to Him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Cited in George Smith, The Life of William Carey, Shoemaker and Missionary (1885)', 'I feel myself happy in my present undertaking; for, though I never felt the loss of social religion so much as now, yet a consciousness of having given up all for God is a support; and the work, with all its attendant inconveniences, is to me a rich reward.', 'perseverance,calling,joy,sacrifice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'I feel myself happy in my present undertaking; for, though I never felt the loss of social religion so much as now, yet a consciousness of having given up all for God is a support; and the work, with all its attendant inconveniences, is to me a rich reward.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 18, 'Cited in George Smith, The Life of William Carey, Shoemaker and Missionary (1885)', 'If he give me credit for being a plodder he will describe me justly. Anything beyond this will be too much. I can plod. I can persevere in any definite pursuit. To this I owe everything.', 'perseverance,diligence,humility,faithfulness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 18 AND text = 'If he give me credit for being a plodder he will describe me justly. Anything beyond this will be too much. I can plod. I can persevere in any definite pursuit. To this I owe everything.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Morning and Evening, February 12, Morning (1865)', 'Great hearts can only be made by great troubles. The spade of trouble digs the reservoir of comfort deeper, and makes more room for consolation.', 'suffering,comfort,hope,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Great hearts can only be made by great troubles. The spade of trouble digs the reservoir of comfort deeper, and makes more room for consolation.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Morning and Evening, February 27, Morning (1865)', 'If he loved me yesterday, he loves me today. My unmoving mansion of rest is my blessed Lord. Let prospects be blighted; let hopes be blasted; let joy be withered; let mildews destroy everything; I have lost nothing of what I have in God.', 'faithfulness,trust,peace,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'If he loved me yesterday, he loves me today. My unmoving mansion of rest is my blessed Lord. Let prospects be blighted; let hopes be blasted; let joy be withered; let mildews destroy everything; I have lost nothing of what I have in God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Morning and Evening, April 2, Evening (1868)', 'Courage, you that prayerfully work and toil for Christ with success of the very smallest kind, it shall not be so always; better times are before you. Your eyes cannot see the blissful future: borrow the telescope of faith; wipe the misty breath of your doubts from the glass; look through it and behold the coming glory.', 'courage,hope,perseverance,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Courage, you that prayerfully work and toil for Christ with success of the very smallest kind, it shall not be so always; better times are before you. Your eyes cannot see the blissful future: borrow the telescope of faith; wipe the misty breath of your doubts from the glass; look through it and behold the coming glory.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Morning and Evening, April 20, Evening (1868)', 'O anxious gazer, look not so much at the battle below, for there thou shalt be enshrouded in smoke, and amazed with garments rolled in blood; but lift thine eyes yonder where the Saviour lives and pleads, for while he intercedes, the cause of God is safe. Let us fight as if it all depended upon us, but let us look up and know that all depends upon him.', 'anxiety,trust,sovereignty,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'O anxious gazer, look not so much at the battle below, for there thou shalt be enshrouded in smoke, and amazed with garments rolled in blood; but lift thine eyes yonder where the Saviour lives and pleads, for while he intercedes, the cause of God is safe. Let us fight as if it all depended upon us, but let us look up and know that all depends upon him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Morning and Evening, April 22, Evening (1868)', 'God our Father is here, and will be here all through the lonely hours; he is an almighty Watcher, a sleepless Guardian, a faithful Friend. Nothing can happen without his direction, for even hell itself is under his control. Darkness is not dark to him.', 'providence,fear,peace,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'God our Father is here, and will be here all through the lonely hours; he is an almighty Watcher, a sleepless Guardian, a faithful Friend. Nothing can happen without his direction, for even hell itself is under his control. Darkness is not dark to him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'All of Grace, Confirmation (1886)', 'Experience and practice confirm our beliefs and our resolutions. Both our joys and our sorrows, our successes and our failures, are sanctified to the selfsame end: even as the tree is helped to root itself both by the soft showers and the rough winds.', 'perseverance,suffering,growth,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Experience and practice confirm our beliefs and our resolutions. Both our joys and our sorrows, our successes and our failures, are sanctified to the selfsame end: even as the tree is helped to root itself both by the soft showers and the rough winds.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'All of Grace, Concerning Deliverance from Sinning (1886)', 'I have seen with my own eyes such marvellous changes of moral and spiritual character that I despair of none. … Thieves are made honest, drunkards sober, liars truthful, and scoffers zealous.', 'hope,grace,transformation,redemption', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'I have seen with my own eyes such marvellous changes of moral and spiritual character that I despair of none. … Thieves are made honest, drunkards sober, liars truthful, and scoffers zealous.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Faith''s Checkbook, December 15 (1888)', 'At present the nations are heavily armed, and are inventing weapons more and more terrible, as if the chief end of man could only be answered by destroying myriads of his fellows. Yet peace will prevail one day; yes, and so prevail that the instruments of destruction shall be beaten into other shapes and used for better purposes.', 'peace,hope,war,justice', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'At present the nations are heavily armed, and are inventing weapons more and more terrible, as if the chief end of man could only be answered by destroying myriads of his fellows. Yet peace will prevail one day; yes, and so prevail that the instruments of destruction shall be beaten into other shapes and used for better purposes.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Faith''s Checkbook, August 17 (1888)', 'The forces which are on the side of the good and the true far outweigh the powers of evil. Therefore, let us keep our spirits up, and walk with the gait of men who possess a cheering secret, which has lifted them above all fear. We are on the winning side.', 'courage,hope,fear,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'The forces which are on the side of the good and the true far outweigh the powers of evil. Therefore, let us keep our spirits up, and walk with the gait of men who possess a cheering secret, which has lifted them above all fear. We are on the winning side.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Around the Wicket Gate (1890)', 'Faith is doing her very best when for many years she plods on, month by month, trusting the Lord about the sick husband, the failing daughter, the declining business, the unconverted friend, and such-like things.', 'faith,perseverance,trust,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Faith is doing her very best when for many years she plods on, month by month, trusting the Lord about the sick husband, the failing daughter, the declining business, the unconverted friend, and such-like things.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Lectures to My Students, Vol. I, The Minister''s Fainting Fits (1875)', 'Fits of depression come over the most of us. Usually cheerful as we may be, we must at intervals be cast down. The strong are not always vigorous, the wise not always ready, the brave not always courageous, and the joyous not always happy.', 'suffering,humility,compassion,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Fits of depression come over the most of us. Usually cheerful as we may be, we must at intervals be cast down. The strong are not always vigorous, the wise not always ready, the brave not always courageous, and the joyous not always happy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'John Ploughman''s Talk, Men Who Are Down (1869)', 'Let it never be forgotten that when a man is down he has a grand opportunity for trusting in God. A false faith can only float in smooth water, but true faith, like a life-boat, is at home in storms.', 'faith,suffering,trust,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Let it never be forgotten that when a man is down he has a grand opportunity for trusting in God. A false faith can only float in smooth water, but true faith, like a life-boat, is at home in storms.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Metropolitan Tabernacle Pulpit, Vol. 30, First King of Righteousness, and After That King of Peace (1884)', 'Righteousness is essential to peace; if it were not first, peace could not be second. … It is needful where an unrighteous peace exists that it should be broken up, that a better peace should be established upon a true foundation which will last for ever.', 'justice,peace,righteousness,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Righteousness is essential to peace; if it were not first, peace could not be second. … It is needful where an unrighteous peace exists that it should be broken up, that a better peace should be established upon a true foundation which will last for ever.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 4, 'Metropolitan Tabernacle Pulpit, Vol. 30, The First Fruit of the Spirit (1884)', 'Our love climbs to heaven, sits among the angels, and anon bows among them in lowliest attitude; but in due time our love stoops down to earth, visits the haunts of depravity, cheers the garrets of poverty, and sanctifies the dens of blasphemy, for it loves the lost. … Love hopes good for all, and plans good for all: while it can soar to glory it can descend to sorrow.', 'love,compassion,service,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 4 AND text = 'Our love climbs to heaven, sits among the angels, and anon bows among them in lowliest attitude; but in due time our love stoops down to earth, visits the haunts of depravity, cheers the garrets of poverty, and sanctifies the dens of blasphemy, for it loves the lost. … Love hopes good for all, and plans good for all: while it can soar to glory it can descend to sorrow.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 2, Letter DCCLXIV, July 12, 1749 (1771)', 'I am content to wait till the day of judgment for the clearing up of my character: and after I am dead, I desire no other epitaph than this, “Here lies G. W. what sort of a man he was, the great day will discover.”', 'humility,patience,truth,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'I am content to wait till the day of judgment for the clearing up of my character: and after I am dead, I desire no other epitaph than this, “Here lies G. W. what sort of a man he was, the great day will discover.”');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 2, Letter DCCXLVII, April 5, 1749 (1771)', 'No, let the name of Whitefield die, so that the cause of JESUS CHRIST may live. I have seen enough of popularity to be sick of it, and did not the interest of my blessed Master require my appearing in public, the world should hear but little of me henceforward.', 'humility,service,discipleship,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'No, let the name of Whitefield die, so that the cause of JESUS CHRIST may live. I have seen enough of popularity to be sick of it, and did not the interest of my blessed Master require my appearing in public, the world should hear but little of me henceforward.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 1, Letter CL, January 16, 1740 (1771)', 'As for my own part, (though I profess myself a minister of the church of England) I am of a catholic spirit; and if I see a man who loves the LORD JESUS in sincerity, I am not very solicitous to what outward communion he belongs.', 'unity,love,church,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'As for my own part, (though I profess myself a minister of the church of England) I am of a catholic spirit; and if I see a man who loves the LORD JESUS in sincerity, I am not very solicitous to what outward communion he belongs.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 6, Sermon XLVII: The Great Duty of Charity Recommended (1771)', 'Let me beseech you, my rich brethren, to consider the poor of the world, and how commendable and praise-worthy it is to relieve those who are distressed. … He could have placed you in their low condition, and they in your high state; it is only his good pleasure that has thus made the difference, and shall not this make you remember your distressed fellow-creatures?', 'compassion,justice,service,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'Let me beseech you, my rich brethren, to consider the poor of the world, and how commendable and praise-worthy it is to relieve those who are distressed. … He could have placed you in their low condition, and they in your high state; it is only his good pleasure that has thus made the difference, and shall not this make you remember your distressed fellow-creatures?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 6, Sermon LIV: Intercession Every Christian''s Duty (1771)', 'When you hear of a notorious sinner, instead of thinking you do well to be angry, beg of JESUS CHRIST to convert, and make him a monument of his free grace; you cannot imagine what a blessed alteration this practice will make in your heart, and how much you will increase day by day in the spirit of love and meekness towards all mankind!', 'prayer,love,grace,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'When you hear of a notorious sinner, instead of thinking you do well to be angry, beg of JESUS CHRIST to convert, and make him a monument of his free grace; you cannot imagine what a blessed alteration this practice will make in your heart, and how much you will increase day by day in the spirit of love and meekness towards all mankind!');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 6, Sermon LV: Persecution Every Christian''s Lot (1771)', 'That which you call prudence, is often, only cowardice, dreadful hypocrisy, pride of heart, which makes you dread contempt, and afraid to give up your reputation for GOD. … I do not desire to court you, but I intreat you to live godly, and fear not contempt for the sake of JESUS CHRIST.', 'courage,boldness,discipleship,holiness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'That which you call prudence, is often, only cowardice, dreadful hypocrisy, pride of heart, which makes you dread contempt, and afraid to give up your reputation for GOD. … I do not desire to court you, but I intreat you to live godly, and fear not contempt for the sake of JESUS CHRIST.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 9, 'The Works of the Reverend George Whitefield, Vol. 6, Sermon XXXVII: The Duty of Searching the Scriptures (1771)', 'Search, therefore, the scriptures, not only devoutly but daily, for in them are the words of eternal life; wait constantly at wisdom’s gate, and she will then, and not till then, display and lay open to you her heavenly treasures.', 'scripture,wisdom,devotion,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 9 AND text = 'Search, therefore, the scriptures, not only devoutly but daily, for in them are the words of eternal life; wait constantly at wisdom’s gate, and she will then, and not till then, display and lay open to you her heavenly treasures.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 1 (1948)', 'To have found God and still to pursue Him is the soul''s paradox of love, scorned indeed by the too-easily-satisfied religionist, but justified in happy experience by the children of the burning heart.', 'faith,worship,love,devotion', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'To have found God and still to pursue Him is the soul''s paradox of love, scorned indeed by the too-easily-satisfied religionist, but justified in happy experience by the children of the burning heart.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 2 (1948)', 'There is within the human heart a tough fibrous root of fallen life whose nature is to possess, always to possess. It covets "things" with a deep and fierce passion.', 'humility,heart,contentment,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'There is within the human heart a tough fibrous root of fallen life whose nature is to possess, always to possess. It covets "things" with a deep and fierce passion.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 3 (1948)', 'The world is perishing for lack of the knowledge of God and the Church is famishing for want of His Presence. The instant cure of most of our religious ills would be to enter the Presence in spiritual experience, to become suddenly aware that we are in God and that God is in us.', 'hope,worship,presence,renewal', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'The world is perishing for lack of the knowledge of God and the Church is famishing for want of His Presence. The instant cure of most of our religious ills would be to enter the Presence in spiritual experience, to become suddenly aware that we are in God and that God is in us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 4 (1948)', 'A spiritual kingdom lies all about us, enclosing us, embracing us, altogether within reach of our inner selves, waiting for us to recognize it.', 'faith,presence,hope,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'A spiritual kingdom lies all about us, enclosing us, embracing us, altogether within reach of our inner selves, waiting for us to recognize it.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 5 (1948)', 'The Presence and the manifestation of the Presence are not the same. There can be the one without the other. God is here when we are wholly unaware of it. He is manifest only when and as we are aware of His Presence.', 'presence,faith,prayer,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'The Presence and the manifestation of the Presence are not the same. There can be the one without the other. God is here when we are wholly unaware of it. He is manifest only when and as we are aware of His Presence.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 6 (1948)', 'God is speaking. Not God spoke, but God is speaking. He is by His nature continuously articulate. He fills the world with His speaking Voice.', 'scripture,creation,word_of_god,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'God is speaking. Not God spoke, but God is speaking. He is by His nature continuously articulate. He fills the world with His speaking Voice.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 7 (1948)', 'Has it ever occurred to you that one hundred pianos all tuned to the same fork are automatically tuned to each other? They are of one accord by being tuned, not to each other, but to another standard to which each one must individually bow.', 'unity,worship,community,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'Has it ever occurred to you that one hundred pianos all tuned to the same fork are automatically tuned to each other? They are of one accord by being tuned, not to each other, but to another standard to which each one must individually bow.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 8 (1948)', 'The moment we make up our minds that we are going on with this determination to exalt God over all we step out of the world''s parade.', 'courage,worship,discipleship,holiness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'The moment we make up our minds that we are going on with this determination to exalt God over all we step out of the world''s parade.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 9 (1948)', 'The heart of the world is breaking under this load of pride and pretense. There is no release from our burden apart from the meekness of Christ.', 'humility,peace,suffering,rest', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'The heart of the world is breaking under this load of pride and pretense. There is no release from our burden apart from the meekness of Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Pursuit of God, Chapter 10 (1948)', 'It is not what a man does that determines whether his work is sacred or secular, it is why he does it. The motive is everything.', 'work,service,calling,holiness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'It is not what a man does that determines whether his work is sacred or secular, it is why he does it. The motive is everything.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Knowledge of the Holy, Chapter 9 (1961)', 'In this world where men forget us, change their attitude toward us as their private interests dictate, and revise their opinion of us for the slightest cause, is it not a source of wondrous strength to know that the God with whom we have to do changes not?', 'faithfulness,hope,courage,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'In this world where men forget us, change their attitude toward us as their private interests dictate, and revise their opinion of us for the slightest cause, is it not a source of wondrous strength to know that the God with whom we have to do changes not?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 19, 'The Knowledge of the Holy, Chapter 22 (1961)', 'Man''s will is free because God is sovereign. A God less than sovereign could not bestow moral freedom upon His creatures.', 'sovereignty,freedom,faith,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 19 AND text = 'Man''s will is free because God is sovereign. A God less than sovereign could not bestow moral freedom upon His creatures.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Studies in the Sermon on the Mount, Vol. 1 (1959)', 'Meekness is essentially a true view of oneself, expressing itself in attitude and conduct with respect to others.', 'humility,character,love,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'Meekness is essentially a true view of oneself, expressing itself in attitude and conduct with respect to others.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Studies in the Sermon on the Mount, Vol. 1 (1959)', 'The peacemaker is one who is not always looking at everything in terms of the effect it has upon himself. Now is not that the whole trouble with us by nature? We look at everything as it affects us.', 'peace,humility,love_of_neighbour,reconciliation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'The peacemaker is one who is not always looking at everything in terms of the effect it has upon himself. Now is not that the whole trouble with us by nature? We look at everything as it affects us.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Spiritual Depression: Its Causes and Cures (1965)', '…the ultimate cause of all spiritual depression is unbelief. For if it were not for unbelief even the devil could do nothing. It is because we listen to the devil instead of listening to God that we go down before him and fall before his attacks.', 'faith,suffering,hope,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = '…the ultimate cause of all spiritual depression is unbelief. For if it were not for unbelief even the devil could do nothing. It is because we listen to the devil instead of listening to God that we go down before him and fall before his attacks.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Spiritual Depression: Its Causes and Cures (1965)', 'Feelings are essential, but if we postulate certain particular feelings as being essential we may very well become victims of the devil and spend the whole of our life in unhappiness…', 'faith,joy,wisdom,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'Feelings are essential, but if we postulate certain particular feelings as being essential we may very well become victims of the devil and spend the whole of our life in unhappiness…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Spiritual Depression: Its Causes and Cures (1965)', 'Faith is a refusal to panic. Do you like that sort of definition of faith? Does that seem to be too earthly and not sufficiently spiritual? It is of the very essence of faith. Faith is a refusal to panic, come what may.', 'faith,courage,peace,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'Faith is a refusal to panic. Do you like that sort of definition of faith? Does that seem to be too earthly and not sufficiently spiritual? It is of the very essence of faith. Faith is a refusal to panic, come what may.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Preaching and Preachers (1971)', 'I would say without any hesitation that the most urgent need in the Christian Church is true preaching; and as it is the greatest and the most urgent need in the Church, it is obviously the greatest need of the world also.', 'preaching,truth,calling,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'I would say without any hesitation that the most urgent need in the Christian Church is true preaching; and as it is the greatest and the most urgent need in the Church, it is obviously the greatest need of the world also.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Preaching and Preachers (1971)', 'What is preaching? Logic on fire! Eloquent reason! Are these contradictions? Of course they are not. Reason concerning this Truth ought to be mightily eloquent, as you see it in the case of the Apostle Paul and others.', 'preaching,truth,wisdom,zeal', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'What is preaching? Logic on fire! Eloquent reason! Are these contradictions? Of course they are not. Reason concerning this Truth ought to be mightily eloquent, as you see it in the case of the Apostle Paul and others.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Authority (1958)', '…the masses of the people are outside the Church. They are there, I suggest, because the Church has in one way or another lost its authority. As a result, the people have ceased to listen or to pay any attention to its message.', 'truth,church,scripture,witness', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = '…the masses of the people are outside the Church. They are there, I suggest, because the Church has in one way or another lost its authority. As a result, the people have ceased to listen or to pay any attention to its message.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Truth Unchanged, Unchanging (1951)', 'Man cannot rehabilitate his true self. He cannot find God. Man can lose his own soul but he can never find it again. He can kill and destroy it but he cannot create it anew.', 'grace,salvation,humility,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'Man cannot rehabilitate his true self. He cannot find God. Man can lose his own soul but he can never find it again. He can kill and destroy it but he cannot create it anew.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Romans: An Exposition, Chapter 8:17-39, The Final Perseverance of the Saints (1975)', 'All things work together for good only to the people specified in the statement, not to anyone else.', 'providence,faith,hope,scripture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'All things work together for good only to the people specified in the statement, not to anyone else.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 22, 'Spiritual Depression: Its Causes and Cures (1965)', 'And then you must go on to remind yourself of God, Who God is, and what God is and what God has done, and what God has pledged Himself to do.', 'hope,faith,providence,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 22 AND text = 'And then you must go on to remind yourself of God, Who God is, and what God is and what God has done, and what God has pledged Himself to do.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures on Revivals of Religion, Lecture 1 (1835)', 'A revival is nothing else than a new beginning of obedience to God. Just as in the case of a converted sinner, the first step is a deep repentance, a breaking down of heart, a getting down into the dust before God, with deep humility, and forsaking of sin.', 'repentance,humility,obedience,renewal', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'A revival is nothing else than a new beginning of obedience to God. Just as in the case of a converted sinner, the first step is a deep repentance, a breaking down of heart, a getting down into the dust before God, with deep humility, and forsaking of sin.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures on Revivals of Religion, Lecture 4 (1835)', 'Prayer is an essential link in the chain of causes that lead to a revival; as much so as truth is. … They overlooked the fact, that truth by itself will never produce the effect, without the Spirit of God.', 'prayer,truth,holy_spirit,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'Prayer is an essential link in the chain of causes that lead to a revival; as much so as truth is. … They overlooked the fact, that truth by itself will never produce the effect, without the Spirit of God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures on Revivals of Religion, Lecture 9 (1835)', 'It is perfectly in the power of the church to regulate the commerce of the world, if they will only themselves maintain perfect integrity. And if Christians will do the same in politics, they will sway the destinies of nations, without involving themselves at all in the base and corrupting strife of parties.', 'integrity,justice,work,citizenship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'It is perfectly in the power of the church to regulate the commerce of the world, if they will only themselves maintain perfect integrity. And if Christians will do the same in politics, they will sway the destinies of nations, without involving themselves at all in the base and corrupting strife of parties.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures on Revivals of Religion, Lecture 15 (1835)', 'Revivals are hindered when ministers and churches take wrong ground in regard to any question involving human rights.', 'justice,human_rights,courage,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'Revivals are hindered when ministers and churches take wrong ground in regard to any question involving human rights.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures on Revivals of Religion, Lecture 15 (1835)', 'God cannot sustain this free and blessed country, which we love and pray for, unless the church will take right ground. Politics are a part of religion in such a country as this, and Christians must do their duty to the country as a part of their duty to God.', 'citizenship,justice,duty,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'God cannot sustain this free and blessed country, which we love and pray for, unless the church will take right ground. Politics are a part of religion in such a country as this, and Christians must do their duty to the country as a part of their duty to God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures on Revivals of Religion, Lecture 19 (1835)', 'Let young converts be taught, plainly, not to calculate upon a life of joy and triumph. They may be called to go through fiery trials. Satan may sift them like wheat. But they must go forward, not calculating so much to be happy as to be useful, not talking about comfort but duty…', 'perseverance,suffering,service,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'Let young converts be taught, plainly, not to calculate upon a life of joy and triumph. They may be called to go through fiery trials. Satan may sift them like wheat. But they must go forward, not calculating so much to be happy as to be useful, not talking about comfort but duty…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Lectures to Professing Christians, Lecture 23 (1837)', 'Perfect love leads a person to obey God, not because he fears the wrath of God, or hopes to be rewarded for doing this or that, but because he loves God and loves to do the will of God.', 'love,obedience,devotion,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'Perfect love leads a person to obey God, not because he fears the wrath of God, or hopes to be rewarded for doing this or that, but because he loves God and loves to do the will of God.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Memoirs of Charles G. Finney, Chapter 2 (1876)', 'Indeed it seemed to come in waves and waves of liquid love; for I could not express it in any other way. It seemed like the very breath of God. … No words can express the wonderful love that was shed abroad in my heart.', 'love,holy_spirit,conversion,joy', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'Indeed it seemed to come in waves and waves of liquid love; for I could not express it in any other way. It seemed like the very breath of God. … No words can express the wonderful love that was shed abroad in my heart.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Memoirs of Charles G. Finney, Chapter 3 (1876)', 'I have a retainer from the Lord Jesus Christ to plead his cause, and I cannot plead yours.', 'calling,courage,discipleship,integrity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'I have a retainer from the Lord Jesus Christ to plead his cause, and I cannot plead yours.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Memoirs of Charles G. Finney, Chapter 23 (1876)', 'After a day of unspeakable wrestling and agony in my soul, just at night, the subject cleared up to my mind. The Spirit led me to believe that all would come out right, and that God had yet a work for me to do; that I might be at rest; that the Lord would go forward with his work, and give me strength to take any part in it that he desired.', 'providence,hope,prayer,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'After a day of unspeakable wrestling and agony in my soul, just at night, the subject cleared up to my mind. The Spirit led me to believe that all would come out right, and that God had yet a work for me to do; that I might be at rest; that the Lord would go forward with his work, and give me strength to take any part in it that he desired.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 61, 'Memoirs of Charles G. Finney, Chapter 23 (1876)', 'When I first went to New York, I had made up my mind on the question of slavery, and was exceedingly anxious to arouse public attention to the subject. I did not, however, turn aside to make it a hobby, or divert the attention of the people from the work of converting souls.', 'justice,courage,mission,conviction', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 61 AND text = 'When I first went to New York, I had made up my mind on the question of slavery, and was exceedingly anxious to arouse public attention to the subject. I did not, however, turn aside to make it a hobby, or divert the attention of the people from the work of converting souls.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'Resolutions, No. 57 (1723)', 'Resolved, when I fear misfortunes and adversity, to examine whether I have done my duty, and resolve to do it and let the event be just as Providence orders it. I will, as far as I can, be concerned about nothing but my duty and my sin.', 'providence,courage,duty,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'Resolved, when I fear misfortunes and adversity, to examine whether I have done my duty, and resolve to do it and let the event be just as Providence orders it. I will, as far as I can, be concerned about nothing but my duty and my sin.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'Resolutions, No. 33 (1722)', 'Resolved, to do always what I can towards making, maintaining, and preserving peace, when it can be done without an overbalancing detriment in other respects.', 'peace,reconciliation,love,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'Resolved, to do always what I can towards making, maintaining, and preserving peace, when it can be done without an overbalancing detriment in other respects.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'Personal Narrative (circa 1740)', 'The soul of a true Christian, as I then wrote my meditations, appeared like such a little white flower as we see in the spring of the year; low and humble on the ground, opening its bosom to receive the pleasant beams of the sun''s glory; rejoicing, as it were, in a calm rapture…', 'humility,creation,joy,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'The soul of a true Christian, as I then wrote my meditations, appeared like such a little white flower as we see in the spring of the year; low and humble on the ground, opening its bosom to receive the pleasant beams of the sun''s glory; rejoicing, as it were, in a calm rapture…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'A Divine and Supernatural Light (1734)', 'He that is spiritually enlightened truly apprehends and sees it, or has a sense of it. He does not merely rationally believe that God is glorious, but he has a sense of the gloriousness of God in his heart.', 'faith,illumination,glory_of_god,heart', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'He that is spiritually enlightened truly apprehends and sees it, or has a sense of it. He does not merely rationally believe that God is glorious, but he has a sense of the gloriousness of God in his heart.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'The Nature of True Virtue, Chapter 1 (1765)', 'True virtue most essentially consists in benevolence to Being in general. Or perhaps, to speak more accurately, it is that consent, propensity, and union of heart to Being in general, which is immediately exercised in a general good will.', 'love,virtue,goodwill,character', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'True virtue most essentially consists in benevolence to Being in general. Or perhaps, to speak more accurately, it is that consent, propensity, and union of heart to Being in general, which is immediately exercised in a general good will.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'A History of the Work of Redemption, Part 10 (1774)', 'God''s providence may not unfitly be compared to a large and long river, having innumerable branches, beginning in different regions, and at a great distance one from another, and all conspiring to one common issue. … The different streams of this river are apt to appear like mere confusion to us, because of our limited sight, whereby we cannot see the whole at once.', 'providence,sovereignty,trust,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'God''s providence may not unfitly be compared to a large and long river, having innumerable branches, beginning in different regions, and at a great distance one from another, and all conspiring to one common issue. … The different streams of this river are apt to appear like mere confusion to us, because of our limited sight, whereby we cannot see the whole at once.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'An Humble Attempt, Part 2 (1747)', 'Such an union in prayer for the general outpouring of the Spirit of God, would not only be beautiful, but profitable too. It would tend very much to promote union and charity between distant members of the church of Christ, to promote public spirit, love to the church of God, and concern for the interest of Zion…', 'prayer,unity,community,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'Such an union in prayer for the general outpouring of the Spirit of God, would not only be beautiful, but profitable too. It would tend very much to promote union and charity between distant members of the church of Christ, to promote public spirit, love to the church of God, and concern for the interest of Zion…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'A Treatise Concerning Religious Affections, Part 1 (1746)', 'If we be not in good earnest in religion, and our wills and inclinations be not strongly exercised, we are nothing. The things of religion are so great, that there can be no suitableness in the exercises of our hearts, to their nature and importance, unless they be lively and powerful.', 'devotion,heart,zeal,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'If we be not in good earnest in religion, and our wills and inclinations be not strongly exercised, we are nothing. The things of religion are so great, that there can be no suitableness in the exercises of our hearts, to their nature and importance, unless they be lively and powerful.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'A Treatise Concerning Religious Affections, Part 3 (1746)', 'Truly gracious affections differ from those affections that are false and delusive, in that they tend to, and are attended with the lamblike, dovelike spirit and temper of Jesus Christ; or in other words, they naturally beget and promote such a spirit of love, meekness, quietness, forgiveness and mercy, as appears in Christ.', 'meekness,forgiveness,mercy,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'Truly gracious affections differ from those affections that are false and delusive, in that they tend to, and are attended with the lamblike, dovelike spirit and temper of Jesus Christ; or in other words, they naturally beget and promote such a spirit of love, meekness, quietness, forgiveness and mercy, as appears in Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'Charity and Its Fruits, Lecture 1 (1852)', 'Love will dispose men to all acts of mercy toward their neighbors when they are under any affliction or calamity, for we are naturally disposed to pity those that we love when they are afflicted.', 'compassion,neighbor,love,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'Love will dispose men to all acts of mercy toward their neighbors when they are under any affliction or calamity, for we are naturally disposed to pity those that we love when they are afflicted.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 8, 'Charity and Its Fruits, Lecture 15 (1852)', 'Love cherished in the soul on earth, will be to us the foretaste of, and the preparation for that world which is a world of love, and where the spirit of love reigns and blesses forever.', 'love,hope,heaven,eternity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 8 AND text = 'Love cherished in the soul on earth, will be to us the foretaste of, and the preparation for that world which is a world of love, and where the spirit of love reigns and blesses forever.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Thoughts Upon Slavery, Section 5 (1774)', 'Liberty is the right of every human creature, as soon as he breathes the vital air. And no human law can deprive him of that right, which he derives from the law of nature.', 'justice,freedom,human_dignity,human_rights', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'Liberty is the right of every human creature, as soon as he breathes the vital air. And no human law can deprive him of that right, which he derives from the law of nature.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Wesley''s Works, Letter to William Wilberforce (1791)', 'Unless God has raised you up for this very thing, you will be worn out by the opposition of men and devils. … Go on, in the name of God, and in the power of his might, till even American slavery (the vilest that ever saw the sun) shall vanish away before it.', 'justice,courage,perseverance,freedom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'Unless God has raised you up for this very thing, you will be worn out by the opposition of men and devils. … Go on, in the name of God, and in the power of his might, till even American slavery (the vilest that ever saw the sun) shall vanish away before it.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'A Plain Account of Christian Perfection (1766)', 'The more care should we take to keep the simple, scriptural account continually in our eye. Pure love reigning alone in the heart and life,—this is the whole of scriptural perfection.', 'love,holiness,scripture,simplicity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'The more care should we take to keep the simple, scriptural account continually in our eye. Pure love reigning alone in the heart and life,—this is the whole of scriptural perfection.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Sermons on Several Occasions, Preface, §10 (1746)', 'For, how far is love, even with many wrong opinions, to be preferred before truth itself without love! We may die without the knowledge of many truths, and yet be carried into Abraham''s bosom. But, if we die without love, what will knowledge avail?', 'love,truth,humility,unity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'For, how far is love, even with many wrong opinions, to be preferred before truth itself without love! We may die without the knowledge of many truths, and yet be carried into Abraham''s bosom. But, if we die without love, what will knowledge avail?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Sermons on Several Occasions, Sermon 23: Upon Our Lord''s Sermon on the Mount, Discourse 3 (1746)', 'They endeavour to calm the stormy spirits of men, to quiet their turbulent passions, to soften the minds of contending parties, and, if possible, reconcile them to each other. They use all innocent arts, and employ all their strength, all the talents which God has given them, as well to preserve peace where it is, as to restore it where it is not.', 'peace,reconciliation,service,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'They endeavour to calm the stormy spirits of men, to quiet their turbulent passions, to soften the minds of contending parties, and, if possible, reconcile them to each other. They use all innocent arts, and employ all their strength, all the talents which God has given them, as well to preserve peace where it is, as to restore it where it is not.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Sermons on Several Occasions, Sermon 24: Upon Our Lord''s Sermon on the Mount, Discourse 4 (1746)', 'Christianity is essentially a social religion; and that to turn it into a solitary religion, is indeed to destroy it.', 'community,discipleship,love,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'Christianity is essentially a social religion; and that to turn it into a solitary religion, is indeed to destroy it.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Sermons on Several Occasions, Sermon 26: Upon Our Lord''s Sermon on the Mount, Discourse 6 (1746)', '…the end of your praying is not to inform God, as though he knew not your wants already; but rather to inform yourselves; to fix the sense of those wants more deeply in your hearts, and the sense of your continual dependence on him who only is able to supply all your wants.', 'prayer,dependence,humility,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = '…the end of your praying is not to inform God, as though he knew not your wants already; but rather to inform yourselves; to fix the sense of those wants more deeply in your hearts, and the sense of your continual dependence on him who only is able to supply all your wants.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Sermons on Several Occasions, Sermon 98: On Visiting the Sick (1786)', 'One great reason why the rich, in general, have so little sympathy for the poor, is, because they so seldom visit them. Hence it is, that, according to the common observation, one part of the world does not know what the other suffers.', 'compassion,poverty,justice,neighbor', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'One great reason why the rich, in general, have so little sympathy for the poor, is, because they so seldom visit them. Hence it is, that, according to the common observation, one part of the world does not know what the other suffers.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Journal of John Wesley (October 20, 1743)', 'I never saw such a chain of providences before; so many convincing proofs, that the hand of God is on every person and thing, overruling all as it seemeth him good.', 'providence,courage,sovereignty,trust', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'I never saw such a chain of providences before; so many convincing proofs, that the hand of God is on every person and thing, overruling all as it seemeth him good.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 5, 'Journal of John Wesley (April 2, 1739)', 'I submitted to be more vile, and proclaimed in the highways the glad tidings of salvation, speaking from a little eminence in a ground adjoining to the city, to about three thousand people.', 'evangelism,humility,mission,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 5 AND text = 'I submitted to be more vile, and proclaimed in the highways the glad tidings of salvation, speaking from a little eminence in a ground adjoining to the city, to about three thousand people.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'The Mortification of Sin, Chapter 1 (1656)', 'The vigour, and power, and comfort of our spiritual life depends on the mortification of the deeds of the flesh.', 'holiness,discipleship,perseverance,spiritual_warfare', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'The vigour, and power, and comfort of our spiritual life depends on the mortification of the deeds of the flesh.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'The Mortification of Sin, Chapter 14 (1656)', 'Set faith at work on Christ for the killing of thy sin. His blood is the great sovereign remedy for sin-sick souls. Live in this, and thou wilt die a conqueror; yea, thou wilt, through the good providence of God, live to see thy lust dead at thy feet.', 'faith,christ,hope,spiritual_warfare', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'Set faith at work on Christ for the killing of thy sin. His blood is the great sovereign remedy for sin-sick souls. Live in this, and thou wilt die a conqueror; yea, thou wilt, through the good providence of God, live to see thy lust dead at thy feet.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'Communion with the Triune God, Part 1, Chapter 4 (1657)', 'So much as we see of the love of God, so much shall we delight in him, and no more.', 'love,joy,faith,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'So much as we see of the love of God, so much shall we delight in him, and no more.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'Communion with the Triune God, Part 1, Chapter 1 (1657)', 'Our communion, then, with God consisteth in his communication of himself unto us, with our returnal unto him of that which he requireth and accepteth, flowing from that union which in Jesus Christ we have with him.', 'prayer,worship,grace,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'Our communion, then, with God consisteth in his communication of himself unto us, with our returnal unto him of that which he requireth and accepteth, flowing from that union which in Jesus Christ we have with him.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'The Glory of Christ, Preface (1684)', 'The revelation made of Christ in the blessed Gospel is far more excellent, more glorious, and more filled with rays of divine wisdom and goodness, than the whole creation and the just comprehension of it, if attainable, can contain or afford. Without the knowledge hereof, the mind of man, however priding itself in other inventions and discoveries, is wrapped up in darkness and confusion.', 'christ,truth,wisdom,creation', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'The revelation made of Christ in the blessed Gospel is far more excellent, more glorious, and more filled with rays of divine wisdom and goodness, than the whole creation and the just comprehension of it, if attainable, can contain or afford. Without the knowledge hereof, the mind of man, however priding itself in other inventions and discoveries, is wrapped up in darkness and confusion.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'The Glory of Christ, Chapter 1 (1684)', 'The hearts of believers are like the needle touched by the loadstone, which cannot rest until it comes to the point whereunto, by the secret virtue of it, it is directed. For being once touched by the love of Christ, receiving therein an impression of secret ineffable virtue, they will ever be in motion, and restless, until they come unto him, and behold his glory.', 'love,christ,hope,worship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'The hearts of believers are like the needle touched by the loadstone, which cannot rest until it comes to the point whereunto, by the secret virtue of it, it is directed. For being once touched by the love of Christ, receiving therein an impression of secret ineffable virtue, they will ever be in motion, and restless, until they come unto him, and behold his glory.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'Of Temptation, Chapter 5 (1658)', 'He that would be little in temptation, let him be much in prayer. This calls in the suitable help and succour that is laid up in Christ for us… This casteth our souls into a frame of opposition to every temptation.', 'prayer,perseverance,spiritual_warfare,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'He that would be little in temptation, let him be much in prayer. This calls in the suitable help and succour that is laid up in Christ for us… This casteth our souls into a frame of opposition to every temptation.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'Of Temptation, Chapter 7 (1658)', 'Gospel provisions will do this work; that is, keep the heart full of a sense of the love of God in Christ. This is the greatest preservative against the power of temptation in the world.', 'love,grace,perseverance,spiritual_warfare', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'Gospel provisions will do this work; that is, keep the heart full of a sense of the love of God in Christ. This is the greatest preservative against the power of temptation in the world.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'The Grace and Duty of Being Spiritually Minded, Preface (1681)', '…the world is at present in a mighty hurry, and being in many places cast off from all foundations of steadfastness, it makes the minds of men giddy with its revolutions, or disorderly in the expectations of them… Hence men walk and talk as if the world were all, when comparatively it is nothing.', 'peace,wisdom,humility,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = '…the world is at present in a mighty hurry, and being in many places cast off from all foundations of steadfastness, it makes the minds of men giddy with its revolutions, or disorderly in the expectations of them… Hence men walk and talk as if the world were all, when comparatively it is nothing.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'The Grace and Duty of Being Spiritually Minded, Chapter 21 (1681)', '"Peace" is taken for a peculiar fruit of the Spirit, consisting in a gracious quietness and composure of mind in the midst of difficulties, temptations, troubles, and such other things as are apt to fill us with fears, despondencies, and disquietments.', 'peace,holy_spirit,suffering,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = '"Peace" is taken for a peculiar fruit of the Spirit, consisting in a gracious quietness and composure of mind in the midst of difficulties, temptations, troubles, and such other things as are apt to fill us with fears, despondencies, and disquietments.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 14, 'Indwelling Sin, Chapter 6 (1667)', 'There are two things that are suited to humble the souls of men, and they are, first, a due consideration of God, and then of themselves… of God, in his greatness, glory, holiness, power, majesty, and authority; of ourselves, in our mean, abject, and sinful condition.', 'humility,sovereignty,repentance,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 14 AND text = 'There are two things that are suited to humble the souls of men, and they are, first, a due consideration of God, and then of themselves… of God, in his greatness, glory, holiness, power, majesty, and authority; of ourselves, in our mean, abject, and sinful condition.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'The Obedience of a Christian Man (1528)', 'Christ is the cause why I love thee, why I am ready to do the uttermost of my power for thee, and why I pray for thee. And as long as the cause abideth, so long lasteth the effect: even as it is always day so long as the sun shineth.', 'love,christ,compassion,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = 'Christ is the cause why I love thee, why I am ready to do the uttermost of my power for thee, and why I pray for thee. And as long as the cause abideth, so long lasteth the effect: even as it is always day so long as the sun shineth.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'The Obedience of a Christian Man (1528)', 'And even in like manner as God maketh the king head over his realm, even so giveth he him commandment to execute the laws upon all men indifferently. For the law is God''s, and not the king''s.', 'justice,authority,truth,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = 'And even in like manner as God maketh the king head over his realm, even so giveth he him commandment to execute the laws upon all men indifferently. For the law is God''s, and not the king''s.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'The Obedience of a Christian Man (1528)', 'The scripture is that wherewith God draweth us unto him, and not wherewith we should be led from him… Thou must therefore go along by the scripture as by a line, until thou come at Christ, which is the way''s end and resting-place.', 'scripture,christ,guidance,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = 'The scripture is that wherewith God draweth us unto him, and not wherewith we should be led from him… Thou must therefore go along by the scripture as by a line, until thou come at Christ, which is the way''s end and resting-place.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'The Obedience of a Christian Man (1528)', 'They will say it cannot be translated into our tongue, it is so rude. It is not so rude as they are false liars. For the Greek tongue agreeth more with the English than with the Latin.', 'scripture,courage,truth,mission', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = 'They will say it cannot be translated into our tongue, it is so rude. It is not so rude as they are false liars. For the Greek tongue agreeth more with the English than with the Latin.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'Tyndale Pentateuch, A Prologue Shewing the Use of the Scripture (1530)', 'Though a man had a precious jewel and a rich, yet if he wist not the value thereof, nor wherefore it served, he were neither the better nor richer of a straw. Even so, though we read the scripture, and babble of it never so much, yet if we know not the use of it, and wherefore it was given, and what is therein to be sought, it profiteth us nothing at all.', 'scripture,wisdom,truth,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = 'Though a man had a precious jewel and a rich, yet if he wist not the value thereof, nor wherefore it served, he were neither the better nor richer of a straw. Even so, though we read the scripture, and babble of it never so much, yet if we know not the use of it, and wherefore it was given, and what is therein to be sought, it profiteth us nothing at all.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'Tyndale New Testament, To the Reader (1526)', 'Apply the gospel, that is to say the promises, unto the deserving of Christ, and to the mercy of God and his truth, and so shalt thou not despair; but shalt feel God as a kind and merciful father.', 'hope,grace,faith,love', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = 'Apply the gospel, that is to say the promises, unto the deserving of Christ, and to the mercy of God and his truth, and so shalt thou not despair; but shalt feel God as a kind and merciful father.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 7, 'The Parable of the Wicked Mammon, Preface to the Reader (1528)', '…they did none other thing than that I looked for: no more shall they do, if they burn me also, if it be God''s will it shall so be. Nevertheless, in translating the New Testament I did my duty, and so do I now, and will do as much more as God hath ordained me to do.', 'courage,calling,perseverance,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 7 AND text = '…they did none other thing than that I looked for: no more shall they do, if they burn me also, if it be God''s will it shall so be. Nevertheless, in translating the New Testament I did my duty, and so do I now, and will do as much more as God hath ordained me to do.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Book of Common Prayer, Collect for the Second Sunday in Advent (1549)', 'Blessed Lord, which hast caused all holy Scriptures to be written for our learning; grant us that we may in such wise hear them, read, mark, learn, and inwardly digest them, that by patience and comfort of thy holy Word, we may embrace and ever hold fast the blessed hope of everlasting life, which thou hast given us in our Saviour Jesus Christ.', 'scripture,hope,perseverance,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = 'Blessed Lord, which hast caused all holy Scriptures to be written for our learning; grant us that we may in such wise hear them, read, mark, learn, and inwardly digest them, that by patience and comfort of thy holy Word, we may embrace and ever hold fast the blessed hope of everlasting life, which thou hast given us in our Saviour Jesus Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Book of Common Prayer, Collect for All Saints (1549)', 'Almighty God, which hast knit together thy elect in one communion and fellowship in the mystical body of thy Son Christ our Lord; grant us grace so to follow thy holy Saints in all virtues, and godly living, that we may come to those unspeakable joys, which thou hast prepared for all them that unfeignedly love thee.', 'community,holiness,hope,prayer', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = 'Almighty God, which hast knit together thy elect in one communion and fellowship in the mystical body of thy Son Christ our Lord; grant us grace so to follow thy holy Saints in all virtues, and godly living, that we may come to those unspeakable joys, which thou hast prepared for all them that unfeignedly love thee.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Book of Common Prayer, The Supper of the Lord and the Holy Communion (1549)', '…grant unto his whole council, and to all that be put in authority under him, that they may truly and indifferently minister justice, to the punishment of wickedness and vice, and to the maintenance of God''s true religion and virtue.', 'justice,prayer,authority,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = '…grant unto his whole council, and to all that be put in authority under him, that they may truly and indifferently minister justice, to the punishment of wickedness and vice, and to the maintenance of God''s true religion and virtue.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Book of Homilies, A Short Declaration of the True, Lively, and Christian Faith, Part 1 (1547)', '…until that kingdom come, he will be our protector and defender in all perils and dangers, whatsoever do chance: and that, though sometime he doth send us sharp adversity, yet that evermore he will be a loving father unto us, correcting us for our sin, but not withdrawing his mercy finally from us, if we trust in him…', 'providence,faith,suffering,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = '…until that kingdom come, he will be our protector and defender in all perils and dangers, whatsoever do chance: and that, though sometime he doth send us sharp adversity, yet that evermore he will be a loving father unto us, correcting us for our sin, but not withdrawing his mercy finally from us, if we trust in him…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Book of Homilies, A Short Declaration of the True, Lively, and Christian Faith, Part 1 (1547)', '…as the light cannot be hid, but will shew forth itself at one place or other; so a true faith cannot be kept secret, but, when occasion is offered, it will break out, and shew itself by good works.', 'faith,service,love,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = '…as the light cannot be hid, but will shew forth itself at one place or other; so a true faith cannot be kept secret, but, when occasion is offered, it will break out, and shew itself by good works.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Preface to the Great Bible (1540)', 'Here may all manner of persons, men, women, young, old, learned, unlearned, rich, poor, priests, laymen, lords, ladies, officers, tenants, and mean men, virgins, wives, widows, lawyers, merchants, artificers, husbandmen, and all manner of persons, of what estate or condition soever they be, may in this book learn all things what they ought to believe, what they ought to do, and what they should not do…', 'scripture,equality,wisdom,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = 'Here may all manner of persons, men, women, young, old, learned, unlearned, rich, poor, priests, laymen, lords, ladies, officers, tenants, and mean men, virgins, wives, widows, lawyers, merchants, artificers, husbandmen, and all manner of persons, of what estate or condition soever they be, may in this book learn all things what they ought to believe, what they ought to do, and what they should not do…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 16, 'Miscellaneous Writings and Letters of Thomas Cranmer, Letter to Queen Mary, September 1555 (1846)', 'He that for fear to lose this life will forsake the truth, shall lose the everlasting life: and he that for the truth''s sake will spend his life, shall find everlasting life… whosoever hath his eyes fixed upon Christ, cannot greatly pass on this life, knowing that he may be sure to have Christ stand by him in the presence of his Father in heaven.', 'courage,truth,hope,perseverance', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 16 AND text = 'He that for fear to lose this life will forsake the truth, shall lose the everlasting life: and he that for the truth''s sake will spend his life, shall find everlasting life… whosoever hath his eyes fixed upon Christ, cannot greatly pass on this life, knowing that he may be sure to have Christ stand by him in the presence of his Father in heaven.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Letters and Papers from Prison, After Ten Years (1953)', 'We have for once learnt to see the great events of world history from below, from the perspective of the outcast, the suspects, the maltreated, the powerless, the oppressed, the reviled — in short, from the perspective of those who suffer.', 'justice,compassion,suffering,humility', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'We have for once learnt to see the great events of world history from below, from the perspective of the outcast, the suspects, the maltreated, the powerless, the oppressed, the reviled — in short, from the perspective of those who suffer.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Letters and Papers from Prison, After Ten Years (1953)', 'The essence of optimism is not its view of the present, but the fact that it is the inspiration of life and hope when others give in; it enables a man to hold his head high when everything seems to be going wrong; it gives him strength to sustain reverses and yet to claim the future for himself instead of abandoning it to his opponent.', 'hope,courage,perseverance,future', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'The essence of optimism is not its view of the present, but the fact that it is the inspiration of life and hope when others give in; it enables a man to hold his head high when everything seems to be going wrong; it gives him strength to sustain reverses and yet to claim the future for himself instead of abandoning it to his opponent.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Letters and Papers from Prison, letter of 24 December 1943 (1953)', '…nothing can make up for the absence of someone whom we love, and it would be wrong to try to find a substitute; we must simply hold out and see it through.', 'grief,love,perseverance,suffering', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = '…nothing can make up for the absence of someone whom we love, and it would be wrong to try to find a substitute; we must simply hold out and see it through.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Letters and Papers from Prison, Outline for a Book (1953)', 'The church is the church only when it exists for others.', 'church,service,love,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'The church is the church only when it exists for others.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'The Cost of Discipleship, Costly Grace (1937)', 'Such grace is costly because it calls us to follow, and it is grace because it calls us to follow Jesus Christ. It is costly because it costs a man his life, and it is grace because it gives a man the only true life.', 'grace,discipleship,cost,obedience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'Such grace is costly because it calls us to follow, and it is grace because it calls us to follow Jesus Christ. It is costly because it costs a man his life, and it is grace because it gives a man the only true life.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'The Cost of Discipleship, The Call to Discipleship (1937)', 'Christianity without the living Christ is inevitably Christianity without discipleship, and Christianity without discipleship is always Christianity without Christ.', 'discipleship,faith,christ,obedience', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'Christianity without the living Christ is inevitably Christianity without discipleship, and Christianity without discipleship is always Christianity without Christ.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'The Cost of Discipleship, The Call to Discipleship (1937)', '…only he who believes is obedient, and only he who is obedient believes.', 'faith,obedience,discipleship,truth', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = '…only he who believes is obedient, and only he who is obedient believes.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Life Together, Community (1939)', 'Christian brotherhood is not an ideal which we must realize; it is rather a reality created by God in Christ in which we may participate.', 'community,grace,love,church', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'Christian brotherhood is not an ideal which we must realize; it is rather a reality created by God in Christ in which we may participate.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Life Together, The Day Alone (1939)', 'A Christian fellowship lives and exists by the intercession of its members for one another, or it collapses.', 'prayer,community,love,intercession', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'A Christian fellowship lives and exists by the intercession of its members for one another, or it collapses.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Life Together, Ministry (1939)', 'We must be ready to allow ourselves to be interrupted by God. God will be constantly crossing our paths and canceling our plans by sending us people with claims and petitions.', 'service,humility,compassion,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'We must be ready to allow ourselves to be interrupted by God. God will be constantly crossing our paths and canceling our plans by sending us people with claims and petitions.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 3, 'Ethics (1949)', 'The Church confesses that she has witnessed the lawless application of brutal force, the physical and spiritual suffering of countless innocent people, oppression, hatred and murder, and that she has not raised her voice on behalf of the victims and has not found ways to hasten to their aid.', 'justice,repentance,moral_courage,church', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 3 AND text = 'The Church confesses that she has witnessed the lawless application of brutal force, the physical and spiritual suffering of countless innocent people, oppression, hatred and murder, and that she has not raised her voice on behalf of the victims and has not found ways to hasten to their aid.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Righteousness of God (1924)', 'We have mistaken our tent for our home; the moratorium for the normal course of things. We have prayed, Thy will be done! and meant by it, Thy will be done not just now!', 'prayer,faith,repentance,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'We have mistaken our tent for our home; the moratorium for the normal course of things. We have prayed, Thy will be done! and meant by it, Thy will be done not just now!');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Righteousness of God (1924)', 'Life receives its meaning again — your own life and life as a whole. Lights of God rise in the darkness, and powers of God become real in weakness.', 'hope,faith,grace,renewal', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'Life receives its meaning again — your own life and life as a whole. Lights of God rise in the darkness, and powers of God become real in weakness.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Strange New World within the Bible (1924)', 'There is a river in the Bible that carries us away, once we have entrusted our destiny to it—away from ourselves to the sea.', 'scripture,faith,trust,surrender', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'There is a river in the Bible that carries us away, once we have entrusted our destiny to it—away from ourselves to the sea.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Strange New World within the Bible (1924)', 'We are offered the magnificent, productive, hopeful life of a grain of seed, a new beginning, out of which all things shall be made new.', 'hope,renewal,kingdom_of_god,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'We are offered the magnificent, productive, hopeful life of a grain of seed, a new beginning, out of which all things shall be made new.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Strange New World within the Bible (1924)', 'It is not the right human thoughts about God which form the content of the Bible, but the right divine thoughts about men. The Bible tells us not how we should talk with God but what he says to us; not how we find the way to him, but how he has sought and found the way to us', 'scripture,grace,revelation,covenant', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'It is not the right human thoughts about God which form the content of the Bible, but the right divine thoughts about men. The Bible tells us not how we should talk with God but what he says to us; not how we find the way to him, but how he has sought and found the way to us');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Christian''s Place in Society (1924)', 'The community of Christ is a building open on every side, for Christ died for all—even for the folk outside.', 'church,love,hospitality,grace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'The community of Christ is a building open on every side, for Christ died for all—even for the folk outside.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Christian''s Place in Society (1924)', 'We throw our energies into the most humdrum tasks, into the business nearest to hand, and also into the making of a new Switzerland and a new Germany, for the reason that we look forward to the new Jerusalem coming down from God out of heaven.', 'hope,work,justice,kingdom_of_god', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'We throw our energies into the most humdrum tasks, into the business nearest to hand, and also into the making of a new Switzerland and a new Germany, for the reason that we look forward to the new Jerusalem coming down from God out of heaven.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'The Word of God and the Word of Man, The Christian''s Place in Society (1924)', 'What can the Christian in society do but follow attentively what is done by God?', 'discipleship,providence,obedience,society', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'What can the Christian in society do but follow attentively what is done by God?');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'Dogmatics in Outline, Faith as Trust (1949)', 'In our glory and in our misery we men are not alone. God comes to meet us and as our Lord and Master He comes to our aid.', 'faith,presence,comfort,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'In our glory and in our misery we men are not alone. God comes to meet us and as our Lord and Master He comes to our aid.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'Dogmatics in Outline, God the Creator (1949)', 'Creation is grace: a statement at which we should like best to pause in reverence, fear and gratitude. God does not grudge the existence of the reality distinct from Himself; He does not grudge it its own reality, nature and freedom.', 'creation,grace,gratitude,freedom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'Creation is grace: a statement at which we should like best to pause in reverence, fear and gratitude. God does not grudge the existence of the reality distinct from Himself; He does not grudge it its own reality, nature and freedom.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 13, 'Evangelical Theology, Prayer (1962)', 'Prayer without study would be empty. Study without prayer would be blind.', 'prayer,study,truth,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 13 AND text = 'Prayer without study would be empty. Study without prayer would be blind.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Scots Confession, Chapter 14 (1560)', '…to save the lives of innocents, to repress tyranny, to defend the oppressed, to keep our bodies clean and holy, to live in sobriety and temperance, to deal justly with all men…are the good works of the second table, which are most pleasing and acceptable unto God', 'justice,compassion,courage,service', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = '…to save the lives of innocents, to repress tyranny, to defend the oppressed, to keep our bodies clean and holy, to live in sobriety and temperance, to deal justly with all men…are the good works of the second table, which are most pleasing and acceptable unto God');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'History of the Reformation in Scotland, Book IV, first interview with Mary Queen of Scots (1561)', 'Madam, as right religion took neither original strength nor authority from worldly princes, but from the Eternal God alone, so are not subjects bound to frame their religion according to the appetites of their princes.', 'truth,conscience,moral_courage,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'Madam, as right religion took neither original strength nor authority from worldly princes, but from the Eternal God alone, so are not subjects bound to frame their religion according to the appetites of their princes.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'History of the Reformation in Scotland, Book IV, first interview with Mary Queen of Scots (1561)', 'God forbid that ever I take upon me to command any to obey me, or yet to set subjects at liberty to do what pleaseth them!', 'obedience,humility,justice,sovereignty', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'God forbid that ever I take upon me to command any to obey me, or yet to set subjects at liberty to do what pleaseth them!');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'History of the Reformation in Scotland, Book III, letter to Queen Elizabeth (1559)', 'It appertaineth to you, therefore, to ground the justice of your authority, not upon that law, which from year to year doth change, but upon the eternal providence of Him, who, contrary to nature, and without your deserving, hath thus exalted your head.', 'justice,leadership,humility,providence', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'It appertaineth to you, therefore, to ground the justice of your authority, not upon that law, which from year to year doth change, but upon the eternal providence of Him, who, contrary to nature, and without your deserving, hath thus exalted your head.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Letter to the Commonalty of Scotland (1558)', 'The verity and truth, being of the nature of fine purified gold, doth not fear the trial of the furnace, but the stubble and chaff of man''s inventions…may not abide the flame of the fire.', 'truth,courage,faith,scripture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'The verity and truth, being of the nature of fine purified gold, doth not fear the trial of the furnace, but the stubble and chaff of man''s inventions…may not abide the flame of the fire.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Letter to the Commonalty of Scotland (1558)', 'The poorest, I say, and most simple, that this day in earth in the days of this cruel persecution, firmly believeth in Christ, and boldly doth confess him before this wicked generation, is no less acceptable before God, neither is judged in his presence to have done any less in promoting Christ his cause, than is the king…', 'equality,courage,faith,human_dignity', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'The poorest, I say, and most simple, that this day in earth in the days of this cruel persecution, firmly believeth in Christ, and boldly doth confess him before this wicked generation, is no less acceptable before God, neither is judged in his presence to have done any less in promoting Christ his cause, than is the king…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Letter to the Commonalty of Scotland (1558)', 'Beloved brethren, ye are God''s creatures, created and formed to his own image and similitude; for whose redemption was shed the most precious blood of the only beloved Son of God…', 'human_dignity,love,redemption,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'Beloved brethren, ye are God''s creatures, created and formed to his own image and similitude; for whose redemption was shed the most precious blood of the only beloved Son of God…');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Sermon on Isaiah 26 (1565)', 'Shall we then think that he will leave his church destitute in this most dangerous age? Only let us stick to his truth, and study to conform our lives to the same, and he shall multiply his knowledge and increase his people.', 'hope,perseverance,truth,church', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'Shall we then think that he will leave his church destitute in this most dangerous age? Only let us stick to his truth, and study to conform our lives to the same, and he shall multiply his knowledge and increase his people.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Sermon on Isaiah 26 (1565)', 'Let us, therefore, that hear these judgments of our God, call for the assistance of his Holy Spirit, that howsoever it pleaseth him to visit us, that we may stoop under his merciful hands, and unfeignedly cry to him when he correcteth us; and so shall we know in experience, that our cries and complaints were not in vain.', 'prayer,humility,suffering,hope', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'Let us, therefore, that hear these judgments of our God, call for the assistance of his Holy Spirit, that howsoever it pleaseth him to visit us, that we may stoop under his merciful hands, and unfeignedly cry to him when he correcteth us; and so shall we know in experience, that our cries and complaints were not in vain.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'History of the Reformation in Scotland, Book IV, interview with Mary Queen of Scots (1563)', 'I never delighted in the weeping of any of God''s creatures. Yea, I can scarcely well abide the tears of my own boys…much less can I rejoice in Your Majesty''s weeping.', 'compassion,truth,integrity,moral_courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = 'I never delighted in the weeping of any of God''s creatures. Yea, I can scarcely well abide the tears of my own boys…much less can I rejoice in Your Majesty''s weeping.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 10, 'Scots Confession, Preface (1560)', '…if any man will note in this our confession any article or sentence repugning to God''s holy word, that it would please him, of his gentleness, and for christian charity''s sake, to admonish us of the same in writ, and we…do promise unto him satisfaction from the mouth of God, that is, from his holy scriptures, or else reformation of that which he shall prove to be amiss.', 'humility,truth,scripture,wisdom', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 10 AND text = '…if any man will note in this our confession any article or sentence repugning to God''s holy word, that it would please him, of his gentleness, and for christian charity''s sake, to admonish us of the same in writ, and we…do promise unto him satisfaction from the mouth of God, that is, from his holy scriptures, or else reformation of that which he shall prove to be amiss.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'Art and the Bible (1973)', 'No work of art is more important than the Christian''s own life, and every Christian is called upon to be an artist in this sense. He may have no gift of writing, no gift of composing or singing, but each man has the gift of creativity in terms of the way he lives his life.', 'calling,creation,discipleship,work', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'No work of art is more important than the Christian''s own life, and every Christian is called upon to be an artist in this sense. He may have no gift of writing, no gift of composing or singing, but each man has the gift of creativity in terms of the way he lives his life.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'Art and the Bible (1973)', 'The Christian is the really free man—he is free to have imagination. This too is our heritage. The Christian is the one whose imagination should fly beyond the stars.', 'creation,freedom,joy,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'The Christian is the really free man—he is free to have imagination. This too is our heritage. The Christian is the one whose imagination should fly beyond the stars.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'No Little People, Chapter 1 (1974)', 'We must remember throughout our lives that in God''s sight there are no little people and no little places. Only one thing is important: to be consecrated persons in God''s place for us, at each moment.', 'humility,calling,service,discipleship', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'We must remember throughout our lives that in God''s sight there are no little people and no little places. Only one thing is important: to be consecrated persons in God''s place for us, at each moment.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'The Mark of the Christian (1970)', 'Love—and the unity it attests to—is the mark Christ gave Christians to wear before the world. Only with this mark may the world know that Christians are indeed Christians and that Jesus was sent by the Father.', 'love,unity,witness,community', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'Love—and the unity it attests to—is the mark Christ gave Christians to wear before the world. Only with this mark may the world know that Christians are indeed Christians and that Jesus was sent by the Father.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'How Should We Then Live? (1976)', 'People have presuppositions, and they will live more consistently on the basis of these presuppositions than even they themselves may realize.', 'truth,wisdom,culture,discernment', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'People have presuppositions, and they will live more consistently on the basis of these presuppositions than even they themselves may realize.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'How Should We Then Live? (1976)', 'Personal peace means just to be let alone, not to be troubled by the troubles of other people, whether across the world or across the city—to live one''s life with minimal possibilities of being personally disturbed.', 'compassion,justice,love,culture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'Personal peace means just to be let alone, not to be troubled by the troubles of other people, whether across the world or across the city—to live one''s life with minimal possibilities of being personally disturbed.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'A Christian Manifesto (1981)', 'True spirituality covers all of reality. There are things the Bible tells us as absolutes which are sinful—which do not conform to the character of God. But aside from these the Lordship of Christ covers all of life and all of life equally.', 'sovereignty,discipleship,truth,culture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'True spirituality covers all of reality. There are things the Bible tells us as absolutes which are sinful—which do not conform to the character of God. But aside from these the Lordship of Christ covers all of life and all of life equally.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'True Spirituality (1971)', 'Further, I think there are two practical tests as to when we are coveting against God or men; first, I am to love God enough to be contented; second, I am to love men enough not to envy.', 'contentment,love,humility,peace', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'Further, I think there are two practical tests as to when we are coveting against God or men; first, I am to love God enough to be contented; second, I am to love men enough not to envy.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'Escape from Reason (1968)', 'Each generation of the church in each setting has the responsibility of communicating the gospel in understandable terms, considering the language and thought-forms of that setting.', 'gospel,witness,culture,calling', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'Each generation of the church in each setting has the responsibility of communicating the gospel in understandable terms, considering the language and thought-forms of that setting.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'Whatever Happened to the Human Race? (1979)', 'We challenge you to be a person in this impersonal age. Be human in this inhuman age. Put the people in your life first—whether perfect or marred.', 'compassion,love,humanity,courage', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'We challenge you to be a person in this impersonal age. Be human in this inhuman age. Put the people in your life first—whether perfect or marred.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'The God Who Is There (1968)', 'The final apologetic, along with the rational, logical defence and presentation, is what the world sees in the individual Christian and in our corporate relationships together.', 'love,witness,community,apologetics', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'The final apologetic, along with the rational, logical defence and presentation, is what the world sees in the individual Christian and in our corporate relationships together.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'He Is There and He Is Not Silent (1972)', 'The infinite-personal God is there, but also he is not silent; that changes the whole world.', 'revelation,truth,hope,faith', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'The infinite-personal God is there, but also he is not silent; that changes the whole world.');
INSERT INTO quotes (figure_id, source, text, themes, verified) SELECT 21, 'A Christian Manifesto (1981)', 'Christianity is not just a series of truths but Truth—Truth about all of reality. And the holding to that Truth intellectually—and then in some poor way living upon that Truth, the Truth of what is—brings forth not only certain personal results, but also governmental and legal results.', 'truth,faith,justice,culture', true WHERE NOT EXISTS (SELECT 1 FROM quotes WHERE figure_id = 21 AND text = 'Christianity is not just a series of truths but Truth—Truth about all of reality. And the holding to that Truth intellectually—and then in some poor way living upon that Truth, the Truth of what is—brings forth not only certain personal results, but also governmental and legal results.');
